        if (cnt < 4) {
            feat_out[6 * i + 0] = 0.33f;
            feat_out[6 * i + 1] = 0.0f;
            feat_out[6 * i + 2] = 1.0f;
            feat_out[6 * i + 3] = 0.0f;
            feat_out[6 * i + 4] = 0.33f;
            feat_out[6 * i + 5] = 0.8f;
