    // Step A: If normals need to be estimated from PCA, compute them first
    if (compute_normals != 0) {
        // Build a 2.5m 3D grid and also track min_z / max_z of coherent surfaces in each XY column
        SpatialGrid tunnel_grid;
        tunnel_grid.build(xyz, n_pts, 2.5f);

        // Map (ix, iy) -> (min_z, max_z) across 2.5m XY columns
        struct ColBounds { float z_min; float z_max; int32_t count; };
        std::unordered_map<uint64_t, ColBounds> xy_cols;
        xy_cols.reserve(tunnel_grid.point_count.size());
        for (size_t c = 0; c < tunnel_grid.point_count.size(); ++c) {
            uint64_t key = (static_cast<uint64_t>(static_cast<uint32_t>(tunnel_grid.cell_ix[c])) << 32ULL) |
                           static_cast<uint64_t>(static_cast<uint32_t>(tunnel_grid.cell_iy[c]));
            auto it = xy_cols.find(key);
            const int32_t start = tunnel_grid.point_start[c];
            const int32_t end = start + tunnel_grid.point_count[c];
            float cmin = xyz[3 * tunnel_grid.sorted_points[start] + 2];
            float cmax = cmin;
            for (int32_t k = start + 1; k < end; ++k) {
                float pz = xyz[3 * tunnel_grid.sorted_points[k] + 2];
                cmin = std::min(cmin, pz);
                cmax = std::max(cmax, pz);
            }
            if (it == xy_cols.end()) {
                xy_cols[key] = {cmin, cmax, tunnel_grid.point_count[c]};
            } else {
                it->second.z_min = std::min(it->second.z_min, cmin);
                it->second.z_max = std::max(it->second.z_max, cmax);
                it->second.count += tunnel_grid.point_count[c];
            }
        }

        #pragma omp parallel for schedule(dynamic, 1024)
        for (int32_t i = 0; i < n_pts; ++i) {
            const float px = xyz[3 * i + 0];
            const float py = xyz[3 * i + 1];
            const float pz = xyz[3 * i + 2];
            int32_t ix, iy, iz;
            grid.point_to_cell(px, py, pz, ix, iy, iz);

            double mx = 0.0, my = 0.0, mz = 0.0;
            double cxx = 0.0, cxy = 0.0, cxz = 0.0, cyy = 0.0, cyz = 0.0, czz = 0.0;
            int32_t cnt = 0;

            for (int32_t dz = -1; dz <= 1; ++dz) {
                for (int32_t dy = -1; dy <= 1; ++dy) {
                    for (int32_t dx = -1; dx <= 1; ++dx) {
                        int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                        if (cid == -1) continue;
                        const int32_t start = grid.point_start[cid];
                        const int32_t end = start + grid.point_count[cid];
                        for (int32_t k = start; k < end; ++k) {
                            int32_t j = grid.sorted_points[k];
                            float qx = xyz[3 * j + 0] - px;
                            float qy = xyz[3 * j + 1] - py;
                            float qz = xyz[3 * j + 2] - pz;
                            if (qx * qx + qy * qy + qz * qz <= r2) {
                                mx += qx; my += qy; mz += qz;
                                cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                                cnt++;
                            }
                        }
                    }
                }
            }

            Eigen::Vector3f n_vec(0.0f, 0.0f, 1.0f);
            if (cnt >= 3) {
                double inv_n = 1.0 / cnt;
                mx *= inv_n; my *= inv_n; mz *= inv_n;
                Eigen::Matrix3f cov;
                cov(0, 0) = static_cast<float>(cxx * inv_n - mx * mx);
                cov(0, 1) = cov(1, 0) = static_cast<float>(cxy * inv_n - mx * my);
                cov(0, 2) = cov(2, 0) = static_cast<float>(cxz * inv_n - mx * mz);
                cov(1, 1) = static_cast<float>(cyy * inv_n - my * my);
                cov(1, 2) = cov(2, 1) = static_cast<float>(cyz * inv_n - my * mz);
                cov(2, 2) = static_cast<float>(czz * inv_n - mz * mz);

                Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> es;
                es.computeDirect(cov);
                n_vec = es.eigenvectors().col(0); // smallest eigenvalue
            }

            // Check XY column Z-span: single-layer terrain vs multi-layer tunnel
            int32_t tix, tiy, tiz;
            tunnel_grid.point_to_cell(px, py, pz, tix, tiy, tiz);
            float col_zmin = pz, col_zmax = pz;
            for (int32_t dy = -1; dy <= 1; ++dy) {
                for (int32_t dx = -1; dx <= 1; ++dx) {
                    uint64_t key = (static_cast<uint64_t>(static_cast<uint32_t>(tix + dx)) << 32ULL) |
                                   static_cast<uint64_t>(static_cast<uint32_t>(tiy + dy));
                    auto it = xy_cols.find(key);
                    if (it != xy_cols.end()) {
                        col_zmin = std::min(col_zmin, it->second.z_min);
                        col_zmax = std::max(col_zmax, it->second.z_max);
                    }
                }
            }

            const float z_span = col_zmax - col_zmin;
            if (z_span < 1.5f) {
                // Single-layer horizontal surface (e.g., exterior ground): orient upward (+Z)
                if (n_vec.z() < 0.0f) n_vec = -n_vec;
            } else {
                // Multi-layer vertical structure: orient toward local 3D tunnel interior centroid
                double tx = 0.0, ty = 0.0;
                int32_t tcnt = 0;
                for (int32_t dz = -1; dz <= 1; ++dz) {
                    for (int32_t dy = -1; dy <= 1; ++dy) {
                        for (int32_t dx = -1; dx <= 1; ++dx) {
                            int32_t cid = tunnel_grid.find_cell(tix + dx, tiy + dy, tiz + dz);
                            if (cid == -1) continue;
                            const int32_t start = tunnel_grid.point_start[cid];
                            const int32_t end = start + tunnel_grid.point_count[cid];
                            for (int32_t k = start; k < end; ++k) {
                                int32_t j = tunnel_grid.sorted_points[k];
                                tx += xyz[3 * j + 0];
                                ty += xyz[3 * j + 1];
                                tcnt++;
                            }
                        }
                    }
                }
                float mid_z = 0.5f * (col_zmin + col_zmax);
                Eigen::Vector3f to_center(
                    tcnt > 0 ? static_cast<float>(tx / tcnt - px) : 0.0f,
                    tcnt > 0 ? static_cast<float>(ty / tcnt - py) : 0.0f,
                    mid_z - pz
                );
                if (n_vec.dot(to_center) < 0.0f) {
                    n_vec = -n_vec;
                }
            }
            normals_inout[3 * i + 0] = n_vec.x();
            normals_inout[3 * i + 1] = n_vec.y();
            normals_inout[3 * i + 2] = n_vec.z();
        }
    }

    // Step B: Compute eigenvalues and sign-invariant normal structure tensor dispersion at radius r
    #pragma omp parallel for schedule(dynamic, 1024)
    for (int32_t i = 0; i < n_pts; ++i) {
        const float px = xyz[3 * i + 0];
        const float py = xyz[3 * i + 1];
        const float pz = xyz[3 * i + 2];
        int32_t ix, iy, iz;
        grid.point_to_cell(px, py, pz, ix, iy, iz);

        double mx = 0.0, my = 0.0, mz = 0.0;
        double cxx = 0.0, cxy = 0.0, cxz = 0.0, cyy = 0.0, cyz = 0.0, czz = 0.0;
        // Sign-invariant normal structure tensor T = (1/m) sum(n_j * n_j^T)
        double nxx = 0.0, nxy = 0.0, nxz = 0.0, nyy = 0.0, nyz = 0.0, nzz = 0.0;
        int32_t cnt = 0;

        for (int32_t dz = -1; dz <= 1; ++dz) {
            for (int32_t dy = -1; dy <= 1; ++dy) {
                for (int32_t dx = -1; dx <= 1; ++dx) {
                    int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                    if (cid == -1) continue;
                    const int32_t start = grid.point_start[cid];
                    const int32_t end = start + grid.point_count[cid];
                    for (int32_t k = start; k < end; ++k) {
                        int32_t j = grid.sorted_points[k];
                        float qx = xyz[3 * j + 0] - px;
                        float qy = xyz[3 * j + 1] - py;
                        float qz = xyz[3 * j + 2] - pz;
                        if (qx * qx + qy * qy + qz * qz <= r2) {
                            mx += qx; my += qy; mz += qz;
                            cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                            cyy += qy * qy; cyz += qy * qz; czz += qz * qz;

                            float njx = normals_inout[3 * j + 0];
                            float njy = normals_inout[3 * j + 1];
                            float njz = normals_inout[3 * j + 2];
                            nxx += njx * njx; nxy += njx * njy; nxz += njx * njz;
                            nyy += njy * njy; nyz += njy * njz; nzz += njz * njz;
                            cnt++;
                        }
                    }
                }
            }
        }

        if (cnt < 4) {
            feat_out[6 * i + 0] = 0.33f;
            feat_out[6 * i + 1] = 0.0f;
            feat_out[6 * i + 2] = 1.0f;
            feat_out[6 * i + 3] = 0.0f;
            feat_out[6 * i + 4] = 0.33f;
            feat_out[6 * i + 5] = 0.8f;
            continue;
        }

        double inv_n = 1.0 / cnt;
        mx *= inv_n; my *= inv_n; mz *= inv_n;
        Eigen::Matrix3f cov;
        cov(0, 0) = static_cast<float>(cxx * inv_n - mx * mx);
        cov(0, 1) = cov(1, 0) = static_cast<float>(cxy * inv_n - mx * my);
        cov(0, 2) = cov(2, 0) = static_cast<float>(cxz * inv_n - mx * mz);
        cov(1, 1) = static_cast<float>(cyy * inv_n - my * my);
        cov(1, 2) = cov(2, 1) = static_cast<float>(cyz * inv_n - my * mz);
        cov(2, 2) = static_cast<float>(czz * inv_n - mz * mz);

        Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> es;
        es.computeDirect(cov, Eigen::EigenvaluesOnly);
        const float l3 = std::max(0.0f, es.eigenvalues()(0));
        const float l2 = std::max(l3, es.eigenvalues()(1));
        const float l1 = std::max(l2, es.eigenvalues()(2));
        const float sum_l = l1 + l2 + l3 + 1e-12f;
        const float l1_eps = l1 + 1e-12f;

        const float rugosity = l3 / sum_l;
        const float planarity = (l2 - l3) / l1_eps;
        const float scattering = l3 / l1_eps;
        const float linearity = (l1 - l2) / l1_eps;
        const float omnivariance = std::cbrt(l1 * l2 * l3) / sum_l;

        // Sign-invariant normal structure tensor largest eigenvalue mu_max in [1/3, 1]
        Eigen::Matrix3f n_cov;
        n_cov(0, 0) = static_cast<float>(nxx * inv_n);
        n_cov(0, 1) = n_cov(1, 0) = static_cast<float>(nxy * inv_n);
        n_cov(0, 2) = n_cov(2, 0) = static_cast<float>(nxz * inv_n);
        n_cov(1, 1) = static_cast<float>(nyy * inv_n);
        n_cov(1, 2) = n_cov(2, 1) = static_cast<float>(nyz * inv_n);
        n_cov(2, 2) = static_cast<float>(nzz * inv_n);

        Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> nes;
        nes.computeDirect(n_cov, Eigen::EigenvaluesOnly);
        const float mu_max = std::clamp(nes.eigenvalues()(2), 0.333333f, 1.0f);
        const float normal_dispersion = std::clamp(1.5f * (1.0f - mu_max), 0.0f, 1.0f);

        feat_out[6 * i + 0] = rugosity;
        feat_out[6 * i + 1] = planarity;
        feat_out[6 * i + 2] = scattering;
        feat_out[6 * i + 3] = linearity;
        feat_out[6 * i + 4] = omnivariance;
        feat_out[6 * i + 5] = normal_dispersion;
    }
}

// -----------------------------------------------------------------------------
// 3. 3D Cone Enclosure & Cavern Roof/Floor Raycasting
// Computes 4 enclosure descriptors per point:
//   enclosure_out[i * 4 + 0] = upward_occlusion (fraction of +Z cone rays hitting any upper surface)
//   enclosure_out[i * 4 + 1] = upward_roof_occlusion (fraction hitting coherent overhanging rock)
//   enclosure_out[i * 4 + 2] = downward_floor_occlusion (fraction of -Z cone rays hitting lower floor)
//   enclosure_out[i * 4 + 3] = cavern_enclosure_score (combined 3D tunnel enclosure in [0, 1])
// -----------------------------------------------------------------------------
void spt_compute_enclosure(
    const float* xyz,
    const float* normals,
    const float* fine_features, // stride 6: [rug, plan, scat, lin, omni, ndisp]
    int32_t n_pts,
    float occ_cell_size,
    float max_range,
    float* enclosure_out
) {
    SpatialGrid grid;
    grid.build(xyz, n_pts, occ_cell_size);
    const int32_t num_cells = static_cast<int32_t>(grid.point_count.size());

    // Precompute per-cell mean normal Z, mean normal dispersion, and mean rugosity
    std::vector<float> cell_mean_nz(num_cells, 0.0f);
    std::vector<float> cell_mean_disp(num_cells, 0.0f);
    std::vector<float> cell_mean_rug(num_cells, 0.0f);

    #pragma omp parallel for schedule(static)
    for (int32_t c = 0; c < num_cells; ++c) {
        const int32_t start = grid.point_start[c];
        const int32_t count = grid.point_count[c];
        double snz = 0.0, sdisp = 0.0, srug = 0.0;
        for (int32_t k = 0; k < count; ++k) {
            int32_t idx = grid.sorted_points[start + k];
            snz += normals[3 * idx + 2];
            srug += fine_features[6 * idx + 0];
            sdisp += fine_features[6 * idx + 5];
        }
        cell_mean_nz[c] = static_cast<float>(snz / count);
        cell_mean_rug[c] = static_cast<float>(srug / count);
        cell_mean_disp[c] = static_cast<float>(sdisp / count);
    }

    // Generate 32 Fibonacci directions inside a 50-degree cone around +Z
    constexpr int K_CONE = 32;
    Eigen::Vector3f up_dirs[K_CONE];
    Eigen::Vector3f down_dirs[K_CONE];
    const float cos_max = std::cos(50.0f * static_cast<float>(M_PI) / 180.0f);
    const float golden_angle = static_cast<float>(M_PI * (3.0 - std::sqrt(5.0)));
    for (int k = 0; k < K_CONE; ++k) {
        float t = (k + 0.5f) / K_CONE;
        float cos_theta = 1.0f - t * (1.0f - cos_max);
        float sin_theta = std::sqrt(std::max(0.0f, 1.0f - cos_theta * cos_theta));
        float phi = k * golden_angle;
        up_dirs[k] = Eigen::Vector3f(sin_theta * std::cos(phi), sin_theta * std::sin(phi), cos_theta);
        down_dirs[k] = Eigen::Vector3f(sin_theta * std::cos(phi), sin_theta * std::sin(phi), -cos_theta);
    }

    // Generate 16 horizontal azimuth directions in XY plane for lateral wall enclosure
    constexpr int K_LAT = 16;
    Eigen::Vector3f lat_dirs[K_LAT];
    for (int k = 0; k < K_LAT; ++k) {
        float phi = 2.0f * static_cast<float>(M_PI) * k / K_LAT;
        lat_dirs[k] = Eigen::Vector3f(std::cos(phi), std::sin(phi), 0.0f);
    }

    const int max_steps = std::max(4, static_cast<int>(std::ceil(max_range / occ_cell_size)));
    const int min_step = std::max(3, static_cast<int>(std::ceil(0.80f / occ_cell_size)));

    #pragma omp parallel for schedule(dynamic, 1024)
    for (int32_t i = 0; i < n_pts; ++i) {
        const float px = xyz[3 * i + 0];
        const float py = xyz[3 * i + 1];
        const float pz = xyz[3 * i + 2];
        const float nz = normals[3 * i + 2];
        const float self_rug = fine_features[6 * i + 0];
        const float self_disp = fine_features[6 * i + 5];
        const float self_rock_coherence =
            std::clamp(1.0f - (self_disp - 0.18f) * 3.0f, 0.0f, 1.0f) *
            std::clamp(1.0f - (self_rug - 0.06f) * 10.0f, 0.0f, 1.0f);

        int up_hits = 0;
        float roof_weighted_hits = 0.0f;

        for (int k = 0; k < K_CONE; ++k) {
            const Eigen::Vector3f& d = up_dirs[k];
            for (int s = min_step; s <= max_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    up_hits++;
                    float c_disp = cell_mean_disp[cid];
                    float c_rug = cell_mean_rug[cid];
                    float c_nz = cell_mean_nz[cid];
                    // Only coherent rock surfaces (low normal dispersion & low rugosity) count as cave roof
                    float disp_w = std::clamp(1.0f - (c_disp - 0.20f) * 3.0f, 0.0f, 1.0f);
                    float rug_w = std::clamp(1.0f - (c_rug - 0.065f) * 10.0f, 0.0f, 1.0f);
                    float overhang_w = (c_nz < -0.05f) ? 1.0f : 0.4f;
                    roof_weighted_hits += disp_w * rug_w * overhang_w;
                    break;
                }
            }
        }

        int down_hits = 0;
        float down_rock_hits = 0.0f;
        for (int k = 0; k < K_CONE; ++k) {
            const Eigen::Vector3f& d = down_dirs[k];
            for (int s = min_step; s <= max_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    down_hits++;
                    float c_disp = cell_mean_disp[cid];
                    float c_rug = cell_mean_rug[cid];
                    float disp_w = std::clamp(1.0f - (c_disp - 0.22f) * 3.0f, 0.0f, 1.0f);
                    float rug_w = std::clamp(1.0f - (c_rug - 0.07f) * 10.0f, 0.0f, 1.0f);
                    down_rock_hits += disp_w * rug_w;
                    break;
                }
            }
        }

        int lat_rock_hits = 0;
        const int max_lat_steps = std::min(max_steps, static_cast<int>(std::ceil(25.0f / occ_cell_size)));
        for (int k = 0; k < K_LAT; ++k) {
            const Eigen::Vector3f& d = lat_dirs[k];
            for (int s = min_step; s <= max_lat_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    if (cell_mean_disp[cid] < 0.28f && cell_mean_rug[cid] < 0.08f) {
                        lat_rock_hits++;
                    }
                    break;
                }
            }
        }

        const float up_occ = static_cast<float>(up_hits) / K_CONE;
        const float roof_occ = roof_weighted_hits / K_CONE;
        const float down_occ = static_cast<float>(down_hits) / K_CONE;
        const float down_rock_occ = down_rock_hits / K_CONE;
        const float lat_occ = static_cast<float>(lat_rock_hits) / K_LAT;

        // Combined 3D cavern enclosure score:
        // - Floor & interior speleothems have high roof_occ (a coherent rock ceiling above them)
        // - Ceiling points (nz < -0.15) are coherent rock themselves and have coherent floor below + lateral walls
        // - Wall points are coherent rock sandwiched between roof_occ and down_rock_occ
        float ceiling_vault_score = 0.0f;
        if (nz < -0.10f) {
            float overhang_strength = std::clamp((-nz - 0.10f) / 0.45f, 0.0f, 1.0f);
            ceiling_vault_score = self_rock_coherence * overhang_strength *
                                  std::max(down_rock_occ, 0.6f * lat_occ);
        }
        float wall_sandwich_score = self_rock_coherence * (
            std::sqrt(roof_occ * down_rock_occ) * 1.4f +
            0.35f * lat_occ * std::max(roof_occ, down_rock_occ)
        );
        float cavern_enclosure = std::clamp(
            std::max({roof_occ, ceiling_vault_score, wall_sandwich_score}), 0.0f, 1.0f
        );

        enclosure_out[4 * i + 0] = up_occ;
        enclosure_out[4 * i + 1] = roof_occ;
        enclosure_out[4 * i + 2] = down_occ;
        enclosure_out[4 * i + 3] = cavern_enclosure;
    }
}

