577:                     float plan_w = std::clamp((c_plan - 0.25f) * 2.5f, 0.0f, 1.0f);
578:                     roof_weighted_hits += disp_w * rug_w * plan_w;
579:                     break;
580:                 }
581:             }
582:         }
583: 
584:         int down_hits = 0;
585:         float down_rock_hits = 0.0f;
586:         for (int k = 0; k < K_CONE; ++k) {
587:             const Eigen::Vector3f& d = down_dirs[k];
588:             for (int s = min_step; s <= max_steps; ++s) {
589:                 float dist = s * occ_cell_size;
590:                 int32_t ix, iy, iz;
591:                 grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
592:                 int32_t cid = grid.find_cell(ix, iy, iz);
593:                 if (cid != -1 && grid.point_count[cid] >= 1) {
594:                     down_hits++;
595:                     float c_disp = cell_mean_disp[cid];
596:                     float c_rug = cell_mean_rug[cid];
597:                     float c_plan = cell_mean_plan[cid];
598:                     float disp_w = std::clamp(1.0f - (c_disp - 0.35f) * 2.5f, 0.0f, 1.0f);
599:                     float rug_w = std::clamp(1.0f - (c_rug - 0.12f) * 8.0f, 0.0f, 1.0f);
600:                     float plan_w = std::clamp((c_plan - 0.25f) * 2.5f, 0.0f, 1.0f);
601:                     down_rock_hits += disp_w * rug_w * plan_w;
602:                     break;
603:                 }
604:             }
605:         }
606: 
607:         int lat_rock_hits = 0;
608:         const int max_lat_steps = std::min(max_steps, static_cast<int>(std::ceil(25.0f / occ_cell_size)));
609:         for (int k = 0; k < K_LAT; ++k) {
610:             const Eigen::Vector3f& d = lat_dirs[k];
611:             for (int s = min_step; s <= max_lat_steps; ++s) {
612:                 float dist = s * occ_cell_size;
613:                 int32_t ix, iy, iz;
614:                 grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz, ix, iy, iz);
615:                 int32_t cid = grid.find_cell(ix, iy, iz);
616:                 if (cid != -1 && grid.point_count[cid] >= 1) {
617:                     if (cell_mean_disp[cid] < 0.38f && cell_mean_rug[cid] < 0.13f && cell_mean_plan[cid] > 0.32f) {
618:                         lat_rock_hits++;
619:                     }
620:                     break;
621:                 }
622:             }
623:         }
624: 
625:         const float up_occ = static_cast<float>(up_hits) / K_CONE;
626:         const float roof_occ = roof_weighted_hits / K_CONE;
627:         const float down_occ = static_cast<float>(down_hits) / K_CONE;
628:         const float down_rock_occ = down_rock_hits / K_CONE;
629:         const float lat_occ = static_cast<float>(lat_rock_hits) / K_LAT;
630: 
631:         // Combined 3D cavern enclosure score:
632:         // 1. Floor / lower walls / internal speleothems: covered by a coherent rock ceiling (roof_occ)
633:         // 2. Overhanging ceiling vaults (nz < -0.10): 2D rock surface with floor below or lateral walls
634:         // 3. Vertical shafts / fissures: 2D rock walls enclosed laterally (lat_occ >= 0.50) and vertically
635:         float ceiling_vault_score = 0.0f;
636:         if (nz < -0.10f) {
637:             float overhang_strength = std::clamp((-nz - 0.10f) / 0.40f, 0.0f, 1.0f);
638:             ceiling_vault_score = self_rock_coherence * overhang_strength *
639:                                   std::max(down_rock_occ, 0.7f * lat_occ);
640:         }
641:         float shaft_wall_score = self_rock_coherence * (
642:             std::sqrt(roof_occ * down_rock_occ) * 1.5f +
643:             0.70f * lat_occ * std::max({roof_occ, (lat_occ >= 0.50f ? down_rock_occ : 0.0f)})
644:         );
645: 
646:         float cavern_enclosure = std::clamp(
647:             std::max({roof_occ, ceiling_vault_score, shaft_wall_score}), 0.0f, 1.0f
648:         );
649: 
650:         enclosure_out[4 * i + 0] = up_occ;
651:         enclosure_out[4 * i + 1] = roof_occ;
652:         enclosure_out[4 * i + 2] = down_occ;
653:         enclosure_out[4 * i + 3] = cavern_enclosure;
654:     }
655: }
