657: // -----------------------------------------------------------------------------
658: // 4. Hierarchical l0-Cut Pursuit Superpoint Partitioning (P0 -> P1 -> P2)
659: // Partitions n_pts points with d_feat features into homogeneous superpoints by
660: // minimizing the l0-cut pursuit energy + minimum component size (cutoff).
661: // Also outputs the superpoint adjacency edge list (u, v) for Stage 5 graph filtering.
662: // -----------------------------------------------------------------------------
663: int32_t spt_partition_superpoints(
664:     const float* xyz,
665:     const float* features, // [n_pts, d_feat]
666:     int32_t n_pts,
667:     int32_t d_feat,
668:     float neighbor_radius,
669:     float reg_strength,
670:     float spatial_weight,
671:     int32_t min_cutoff,
672:     int32_t* sp_labels_out
673: ) {
674:     if (n_pts <= 0) return 0;
675: 
676:     SpatialGrid grid;
677:     grid.build(xyz, n_pts, neighbor_radius);
678:     const float r2 = neighbor_radius * neighbor_radius;
679: 
680:     // Build radius/kNN adjacency list (up to k=12 nearest neighbors per point)
681:     constexpr int MAX_K = 12;
682:     std::vector<int32_t> adj_indices(static_cast<size_t>(n_pts) * MAX_K, -1);
683:     std::vector<int32_t> adj_counts(n_pts, 0);
684: 
685:     #pragma omp parallel for schedule(dynamic, 1024)
686:     for (int32_t i = 0; i < n_pts; ++i) {
687:         const float px = xyz[3 * i + 0];
688:         const float py = xyz[3 * i + 1];
689:         const float pz = xyz[3 * i + 2];
690:         int32_t ix, iy, iz;
691:         grid.point_to_cell(px, py, pz, ix, iy, iz);
692: 
693:         std::pair<float, int32_t> cand[64];
694:         int n_cand = 0;
695: 
696:         for (int32_t dz = -1; dz <= 1; ++dz) {
697:             for (int32_t dy = -1; dy <= 1; ++dy) {
698:                 for (int32_t dx = -1; dx <= 1; ++dx) {
699:                     int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
700:                     if (cid == -1) continue;
701:                     const int32_t start = grid.point_start[cid];
702:                     const int32_t end = start + grid.point_count[cid];
703:                     for (int32_t k = start; k < end; ++k) {
704:                         int32_t j = grid.sorted_points[k];
705:                         if (j == i) continue;
706:                         float qx = xyz[3 * j + 0] - px;
707:                         float qy = xyz[3 * j + 1] - py;
708:                         float qz = xyz[3 * j + 2] - pz;
709:                         float d2 = qx * qx + qy * qy + qz * qz;
710:                         if (d2 <= r2) {
711:                             if (n_cand < 64) {
712:                                 cand[n_cand++] = {d2, j};
713:                             } else if (d2 < cand[n_cand - 1].first) {
714:                                 cand[n_cand - 1] = {d2, j};
715:                             }
716:                         }
717:                     }
718:                 }
719:             }
720:         }
721:         std::sort(cand, cand + n_cand);
722:         int keep = std::min(n_cand, MAX_K);
723:         adj_counts[i] = keep;
724:         for (int k = 0; k < keep; ++k) {
725:             adj_indices[static_cast<size_t>(i) * MAX_K + k] = cand[k].second;
726:         }
727:     }
728: 
729:     // Disjoint-set (Union-Find) with component feature centroids & sizes for l0-cut pursuit
730:     std::vector<int32_t> parent(n_pts);
731:     std::vector<int32_t> comp_size(n_pts, 1);
732:     std::vector<float> comp_feat(static_cast<size_t>(n_pts) * d_feat);
733:     std::vector<float> comp_xyz(static_cast<size_t>(n_pts) * 3);
734: 
735:     for (int32_t i = 0; i < n_pts; ++i) {
736:         parent[i] = i;
737:         for (int d = 0; d < d_feat; ++d) {
738:             comp_feat[static_cast<size_t>(i) * d_feat + d] = features[static_cast<size_t>(i) * d_feat + d];
739:         }
740:         comp_xyz[3 * i + 0] = xyz[3 * i + 0];
741:         comp_xyz[3 * i + 1] = xyz[3 * i + 1];
742:         comp_xyz[3 * i + 2] = xyz[3 * i + 2];
743:     }
744: 
745:     auto find_root = [&](int32_t u) {
746:         while (parent[u] != u) {
747:             parent[u] = parent[parent[u]];
748:             u = parent[u];
749:         }
750:         return u;
751:     };
752: 
753:     auto merge_Select = [&](int32_t ru, int32_t rv) {
754:         if (ru == rv) return ru;
755:         if (comp_size[ru] < comp_size[rv]) std::swap(ru, rv);
756:         const float su = static_cast<float>(comp_size[ru]);
757:         const float sv = static_cast<float>(comp_size[rv]);
758:         const float inv_s = 1.0f / (su + sv);
759:         for (int d = 0; d < d_feat; ++d) {
760:             comp_feat[static_cast<size_t>(ru) * d_feat + d] =
761:                 (comp_feat[static_cast<size_t>(ru) * d_feat + d] * su +
762:                  comp_feat[static_cast<size_t>(rv) * d_feat + d] * sv) * inv_s;
763:         }
764:         for (int d = 0; d < 3; ++d) {
765:             comp_xyz[3 * ru + d] = (comp_xyz[3 * ru + d] * su + comp_xyz[3 * rv + d] * sv) * inv_s;
766:         }
767:         parent[rv] = ru;
768:         comp_size[ru] += comp_size[rv];
769:         return ru;
770:     };
771: 
772:     // Multi-pass l0-cut pursuit region merging with progressively increasing threshold up to reg_strength
773:     const float thresholds[4] = {
774:         reg_strength * 0.15f,
775:         reg_strength * 0.40f,
776:         reg_strength * 0.75f,
777:         reg_strength
778:     };
779: 
780:     for (int pass = 0; pass < 4; ++pass) {
781:         const float thresh = thresholds[pass];
782:         for (int32_t i = 0; i < n_pts; ++i) {
783:             int32_t ru = find_root(i);
784:             const int deg = adj_counts[i];
785:             for (int k = 0; k < deg; ++k) {
786:                 int32_t j = adj_indices[static_cast<size_t>(i) * MAX_K + k];
787:                 int32_t rv = find_root(j);
788:                 if (ru == rv) continue;
789: 
790:                 // Compute Ward / l0-cut pursuit merge cost between superpoints ru and rv
791:                 float feat_dist2 = 0.0f;
792:                 for (int d = 0; d < d_feat; ++d) {
793:                     float diff = comp_feat[static_cast<size_t>(ru) * d_feat + d] -
794:                                  comp_feat[static_cast<size_t>(rv) * d_feat + d];
795:                     feat_dist2 += diff * diff;
796:                 }
797:                 float dx = comp_xyz[3 * ru + 0] - comp_xyz[3 * rv + 0];
798:                 float dy = comp_xyz[3 * ru + 1] - comp_xyz[3 * rv + 1];
799:                 float dz = comp_xyz[3 * ru + 2] - comp_xyz[3 * rv + 2];
800:                 float sp_dist2 = (dx * dx + dy * dy + dz * dz) * spatial_weight;
801: 
802:                 float total_cost = feat_dist2 + sp_dist2;
803:                 if (total_cost <= thresh) {
804:                     ru = merge_Select(ru, rv);
805:                 }
806:             }
807:         }
808:     }
809: 
810:     // Enforce minimum component size (min_cutoff) by merging small fragments into closest neighbor
811:     for (int iter = 0; iter < 3; ++iter) {
812:         for (int32_t i = 0; i < n_pts; ++i) {
813:             int32_t ru = find_root(i);
814:             if (comp_size[ru] >= min_cutoff) continue;
815: 
816:             const int deg = adj_counts[i];
817:             int32_t best_rv = -1;
818:             float best_cost = 1e30f;
819:             for (int k = 0; k < deg; ++k) {
820:                 int32_t j = adj_indices[static_cast<size_t>(i) * MAX_K + k];
821:                 int32_t rv = find_root(j);
822:                 if (ru == rv) continue;
823: 
824:                 float feat_dist2 = 0.0f;
825:                 for (int d = 0; d < d_feat; ++d) {
826:                     float diff = comp_feat[static_cast<size_t>(ru) * d_feat + d] -
827:                                  comp_feat[static_cast<size_t>(rv) * d_feat + d];
828:                     feat_dist2 += diff * diff;
829:                 }
830:                 if (feat_dist2 < best_cost) {
831:                     best_cost = feat_dist2;
832:                     best_rv = rv;
833:                 }
834:             }
835:             if (best_rv != -1) {
836:                 merge_Select(ru, best_rv);
837:             }
838:         }
839:     }
840: 
841:     // Relabel components contiguously 0 .. num_sp - 1
842:     std::vector<int32_t> root_to_id(n_pts, -1);
843:     int32_t num_sp = 0;
844:     for (int32_t i = 0; i < n_pts; ++i) {
845:         int32_t r = find_root(i);
846:         if (root_to_id[r] == -1) {
847:             root_to_id[r] = num_sp++;
848:         }
849:         sp_labels_out[i] = root_to_id[r];
850:     }
851:     return num_sp;
852: }
853: 
854: // -----------------------------------------------------------------------------
855: // 5. Exact Superpoint Boundary Adjacency Graph Extraction
856: // Connects superpoints u and v if any constituent P0 points lie within adj_radius.
857: // Writes up to max_edges undirected edges (u < v) to edge_u_out and edge_v_out.
858: // -----------------------------------------------------------------------------
859: int32_t spt_build_superpoint_graph(
860:     const float* xyz,
861:     const int32_t* sp_labels,
862:     int32_t n_pts,
863:     int32_t num_sp,
864:     float adj_radius,
865:     int32_t max_edges,
866:     int32_t* edge_u_out,
867:     int32_t* edge_v_out
868: ) {
869:     if (n_pts <= 0 || num_sp <= 1) return 0;
870: 
871:     SpatialGrid grid;
872:     grid.build(xyz, n_pts, adj_radius);
873:     const float r2 = adj_radius * adj_radius;
874: 
875:     const int n_threads = omp_get_max_threads();
876:     std::vector<std::vector<uint64_t>> thread_edges(n_threads);
877: 
878:     #pragma omp parallel
879:     {
880:         const int tid = omp_get_thread_num();
881:         auto& local_vec = thread_edges[tid];
882:         local_vec.reserve(4096);
883: 
884:         #pragma omp for schedule(dynamic, 1024)
885:         for (int32_t i = 0; i < n_pts; ++i) {
886:             const int32_t sp_u = sp_labels[i];
887:             const float px = xyz[3 * i + 0];
888:             const float py = xyz[3 * i + 1];
889:             const float pz = xyz[3 * i + 2];
890:             int32_t ix, iy, iz;
891:             grid.point_to_cell(px, py, pz, ix, iy, iz);
892: 
893:             for (int32_t dz = -1; dz <= 1; ++dz) {
894:                 for (int32_t dy = -1; dy <= 1; ++dy) {
895:                     for (int32_t dx = -1; dx <= 1; ++dx) {
896:                         int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
897:                         if (cid == -1) continue;
898:                         const int32_t start = grid.point_start[cid];
899:                         const int32_t end = start + grid.point_count[cid];
900:                         for (int32_t k = start; k < end; ++k) {
901:                             int32_t j = grid.sorted_points[k];
902:                             int32_t sp_v = sp_labels[j];
903:                             if (sp_u >= sp_v) continue;
904:                             float qx = xyz[3 * j + 0] - px;
905:                             float qy = xyz[3 * j + 1] - py;
906:                             float qz = xyz[3 * j + 2] - pz;
907:                             if (qx * qx + qy * qy + qz * qz <= r2) {
908:                                 uint64_t key = (static_cast<uint64_t>(static_cast<uint32_t>(sp_u)) << 32ULL) |
909:                                                static_cast<uint64_t>(static_cast<uint32_t>(sp_v));
910:                                 local_vec.push_back(key);
911:                             }
912:                         }
913:                     }
914:                 }
915:             }
916:         }
917:         std::sort(local_vec.begin(), local_vec.end());
918:         local_vec.erase(std::unique(local_vec.begin(), local_vec.end()), local_vec.end());
919:     }
920: 
921:     std::vector<uint64_t> all_edges;
922:     for (int t = 0; t < n_threads; ++t) {
923:         all_edges.insert(all_edges.end(), thread_edges[t].begin(), thread_edges[t].end());
924:     }
925:     std::sort(all_edges.begin(), all_edges.end());
926:     all_edges.erase(std::unique(all_edges.begin(), all_edges.end()), all_edges.end());
927: 
928:     const int32_t count = std::min(static_cast<int32_t>(all_edges.size()), max_edges);
929:     for (int32_t e = 0; e < count; ++e) {
930:         edge_u_out[e] = static_cast<int32_t>(all_edges[e] >> 32ULL);
931:         edge_v_out[e] = static_cast<int32_t>(all_edges[e] & 0xFFFFFFFFULL);
932:     }
933:     return count;
934: }
