53: std::vector<wnnc::Vec3<Scalar>> normalizeToUnitCube(const mesh_reconstruction::Point_set& points) {
54:     if (points.empty()) return {};
55:     constexpr double kBoundingBoxScale = 1.1;
56: 
57:     auto it = points.begin();
58:     auto first_p = points.point(*it);
59:     wnnc::Vec3<double> boxMin{first_p.x(), first_p.y(), first_p.z()};
60:     wnnc::Vec3<double> boxMax = boxMin;
61:     for (; it != points.end(); ++it) {
62:         auto p = points.point(*it);
63:         boxMin = {std::min(boxMin.x, p.x()), std::min(boxMin.y, p.y()), std::min(boxMin.z, p.z())};
64:         boxMax = {std::max(boxMax.x, p.x()), std::max(boxMax.y, p.y()), std::max(boxMax.z, p.z())};
65:     }
66:     const wnnc::Vec3<double> center = (boxMin + boxMax) * 0.5;
67:     const wnnc::Vec3<double> extent = boxMax - boxMin;
68:     const double longestSide = std::max({extent.x, extent.y, extent.z});
69:     const double scale = 2.0 / (longestSide * kBoundingBoxScale);
70: 
71:     std::vector<wnnc::Vec3<Scalar>> normalized;
72:     normalized.reserve(points.size());
73:     for (auto jt = points.begin(); jt != points.end(); ++jt) {
74:         auto p = points.point(*jt);
75:         normalized.push_back((((wnnc::Vec3<double>{p.x(), p.y(), p.z()}) - center) * scale).template cast<Scalar>());
76:     }
77:     return normalized;
78: }
