12: namespace wnnc {
13: 
14: struct SolverSettings {
15:     int iterations = 40;
16:     /// Smoothing width is annealed linearly from `widthMax` (first iteration)
17:     /// down to `widthMin` (last iteration).
18:     double widthMin = 0.002;
19:     double widthMax = 0.016;
20: };
21: 
22: /// Called after each iteration with (completedIterations, totalIterations).
23: using IterationCallback = std::function<void(int, int)>;
24: 
25: /// WNNC normal estimation (the iterative method of Lin et al. 2024, i.e. the
26: /// main loop of the reference `main_wnnc.py`).
27: ///
28: /// Starting from mu = 0, each iteration performs:
29: ///  1. A gradient step with exact line search on || A mu - 0.5 ||^2, the
30: ///     requirement that every sample lies on the 0.5 winding-number level
31: ///     set:  r = A^T (0.5 - A mu),  mu += (<r,r> / <A r, A r>) r.
32: ///  2. The WNNC step: replace each mu_i's direction with the direction of
33: ///     the winding-number field gradient (G mu)_i, keeping its length.
34: ///
35: /// Returns the unit normals of the final iteration.
36: template <typename Scalar>
37: std::vector<Vec3<Scalar>> estimateNormals(const WindingNumberOperator<Scalar>& windingNumber,
38:                                           const SolverSettings& settings,
39:                                           const IterationCallback& onIteration = {}) {
40:     const Index pointCount = windingNumber.pointCount();
41:     const auto n = static_cast<std::size_t>(pointCount);
42: 
43:     // Every sample sits on the surface, where the winding number jumps from
44:     // 0 (outside) to 1 (inside); its smoothed value there is the target 0.5.
45:     constexpr Scalar kTargetWindingNumber = Scalar(0.5);
46: 
47:     std::vector<Vec3<Scalar>> mu(n);  // current area-weighted normals
48:     std::vector<Vec3<Scalar>> unitNormals(n);
49:     std::vector<Scalar> smoothingWidths(n);
50: 
51:     for (int iteration = 0; iteration < settings.iterations; ++iteration) {
52:         const double annealing =
53:             settings.iterations > 1
54:                 ? static_cast<double>(settings.iterations - 1 - iteration) /
55:                       static_cast<double>(settings.iterations - 1)
56:                 : 0.0;
57:         const auto width = static_cast<Scalar>(
58:             settings.widthMin + annealing * (settings.widthMax - settings.widthMin));
59:         std::fill(smoothingWidths.begin(), smoothingWidths.end(), width);
60: 
61:         // Gradient step with exact line search: r = A^T (0.5 - A mu).
62:         // (The reference evaluates A^T 0.5 and A^T A mu as two treecode
63:         // passes; by linearity one pass over the defect is identical, up to
64:         // the treecode's far-field approximation.)
65:         std::vector<Scalar> defect = windingNumber.applyA(mu, smoothingWidths);
66:         for (std::size_t i = 0; i < n; ++i) {
67:             defect[i] = kTargetWindingNumber - defect[i];
68:         }
69:         const std::vector<Vec3<Scalar>> residual =
70:             windingNumber.applyATransposed(defect, smoothingWidths);
71:         const std::vector<Scalar> aResidual = windingNumber.applyA(residual, smoothingWidths);
72: 
73:         double residualNormSq = 0.0;
74:         double aResidualNormSq = 0.0;
75:         for (std::size_t i = 0; i < n; ++i) {
76:             residualNormSq += static_cast<double>(residual[i].squaredNorm());
77:             aResidualNormSq += static_cast<double>(aResidual[i]) * static_cast<double>(aResidual[i]);
78:         }
79:         if (aResidualNormSq == 0.0) {
80:             break;  // stationary point; avoids a division by zero
81:         }
82:         const auto stepSize = static_cast<Scalar>(residualNormSq / aResidualNormSq);
83:         for (std::size_t i = 0; i < n; ++i) {
84:             mu[i] += residual[i] * stepSize;
85:         }
86: 
87:         // WNNC step: new directions from the field gradient, lengths kept.
88:         const std::vector<Vec3<Scalar>> gradients = windingNumber.applyG(mu, smoothingWidths);
89:         for (std::size_t i = 0; i < n; ++i) {
90:             unitNormals[i] = gradients[i].normalized();
91:             mu[i] = unitNormals[i] * mu[i].norm();
92:         }
93: 
94:         if (onIteration) {
95:             onIteration(iteration + 1, settings.iterations);
96:         }
97:     }
98:     return unitNormals;
99: }
