743:     if (n_pts <= 0) return 0;
744: 
745:     SpatialGrid grid;
746:     grid.build(xyz, n_pts, neighbor_radius);
747:     const float r2 = neighbor_radius * neighbor_radius;
748: 
749:     // Build radius/kNN adjacency list (up to k=12 nearest neighbors per point)
750:     constexpr int MAX_K = 12;
751:     std::vector<int32_t> adj_indices(static_cast<size_t>(n_pts) * MAX_K, -1);
752:     std::vector<int32_t> adj_counts(n_pts, 0);
753: 
754:     #pragma omp parallel for schedule(dynamic, 1024)
755:     for (int32_t i = 0; i < n_pts; ++i) {
756:         const float px = xyz[3 * i + 0];
757:         const float py = xyz[3 * i + 1];
758:         const float pz = xyz[3 * i + 2];
759:         int32_t ix, iy, iz;
760:         grid.point_to_cell(px, py, pz, ix, iy, iz);
761: 
762:         std::pair<float, int32_t> cand[64];
763:         int n_cand = 0;
764: 
765:         for (int32_t dz = -1; dz <= 1; ++dz) {
766:             for (int32_t dy = -1; dy <= 1; ++dy) {
767:                 for (int32_t dx = -1; dx <= 1; ++dx) {
768:                     int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
769:                     if (cid == -1) continue;
770:                     const int32_t start = grid.point_start[cid];
771:                     const int32_t end = start + grid.point_count[cid];
772:                     for (int32_t k = start; k < end; ++k) {
773:                         int32_t j = grid.sorted_points[k];
774:                         if (j == i) continue;
775:                         float qx = xyz[3 * j + 0] - px;
776:                         float qy = xyz[3 * j + 1] - py;
777:                         float qz = xyz[3 * j + 2] - pz;
778:                         float d2 = qx * qx + qy * qy + qz * qz;
779:                         if (d2 <= r2) {
780:                             if (n_cand < 64) {
781:                                 cand[n_cand++] = {d2, j};
782:                             } else if (d2 < cand[n_cand - 1].first) {
783:                                 cand[n_cand - 1] = {d2, j};
784:                             }
785:                         }
786:                     }
787:                 }
788:             }
789:         }
790:         std::sort(cand, cand + n_cand);
791:         int keep = std::min(n_cand, MAX_K);
792:         adj_counts[i] = keep;
793:         for (int k = 0; k < keep; ++k) {
794:             adj_indices[static_cast<size_t>(i) * MAX_K + k] = cand[k].second;
795:         }
796:     }
797: 
798:     // Disjoint-set (Union-Find) with component feature centroids & sizes for l0-cut pursuit
799:     std::vector<int32_t> parent(n_pts);
800:     std::vector<int32_t> comp_size(n_pts, 1);
801:     std::vector<float> comp_feat(static_cast<size_t>(n_pts) * d_feat);
802:     std::vector<float> comp_xyz(static_cast<size_t>(n_pts) * 3);
803: 
804:     for (int32_t i = 0; i < n_pts; ++i) {
805:         parent[i] = i;
806:         for (int d = 0; d < d_feat; ++d) {
807:             comp_feat[static_cast<size_t>(i) * d_feat + d] = features[static_cast<size_t>(i) * d_feat + d];
808:         }
809:         comp_xyz[3 * i + 0] = xyz[3 * i + 0];
810:         comp_xyz[3 * i + 1] = xyz[3 * i + 1];
811:         comp_xyz[3 * i + 2] = xyz[3 * i + 2];
812:     }
813: 
814:     auto find_root = [&](int32_t u) {
815:         while (parent[u] != u) {
816:             parent[u] = parent[parent[u]];
817:             u = parent[u];
818:         }
819:         return u;
820:     };
821: 
822:     auto merge_Select = [&](int32_t ru, int32_t rv) {
823:         if (ru == rv) return ru;
824:         if (comp_size[ru] < comp_size[rv]) std::swap(ru, rv);
825:         const float su = static_cast<float>(comp_size[ru]);
826:         const float sv = static_cast<float>(comp_size[rv]);
827:         const float inv_s = 1.0f / (su + sv);
828:         for (int d = 0; d < d_feat; ++d) {
829:             comp_feat[static_cast<size_t>(ru) * d_feat + d] =
830:                 (comp_feat[static_cast<size_t>(ru) * d_feat + d] * su +
831:                  comp_feat[static_cast<size_t>(rv) * d_feat + d] * sv) * inv_s;
832:         }
833:         for (int d = 0; d < 3; ++d) {
834:             comp_xyz[3 * ru + d] = (comp_xyz[3 * ru + d] * su + comp_xyz[3 * rv + d] * sv) * inv_s;
835:         }
836:         parent[rv] = ru;
837:         comp_size[ru] += comp_size[rv];
838:         return ru;
839:     };
840: 
841:     // Multi-pass l0-cut pursuit region merging with progressively increasing threshold up to reg_strength
842:     const float thresholds[4] = {
843:         reg_strength * 0.15f,
844:         reg_strength * 0.40f,
845:         reg_strength * 0.75f,
846:         reg_strength
847:     };
848: 
849:     for (int pass = 0; pass < 4; ++pass) {
850:         const float thresh = thresholds[pass];
851:         for (int32_t i = 0; i < n_pts; ++i) {
852:             int32_t ru = find_root(i);
853:             const int deg = adj_counts[i];
854:             for (int k = 0; k < deg; ++k) {
855:                 int32_t j = adj_indices[static_cast<size_t>(i) * MAX_K + k];
856:                 int32_t rv = find_root(j);
857:                 if (ru == rv) continue;
858: 
859:                 // Compute Ward / l0-cut pursuit merge cost between superpoints ru and rv
860:                 float feat_dist2 = 0.0f;
861:                 for (int d = 0; d < d_feat; ++d) {
862:                     float diff = comp_feat[static_cast<size_t>(ru) * d_feat + d] -
863:                                  comp_feat[static_cast<size_t>(rv) * d_feat + d];
864:                     feat_dist2 += diff * diff;
865:                 }
866:                 float dx = comp_xyz[3 * ru + 0] - comp_xyz[3 * rv + 0];
867:                 float dy = comp_xyz[3 * ru + 1] - comp_xyz[3 * rv + 1];
868:                 float dz = comp_xyz[3 * ru + 2] - comp_xyz[3 * rv + 2];
869:                 float sp_dist2 = (dx * dx + dy * dy + dz * dz) * spatial_weight;
870: 
871:                 float total_cost = feat_dist2 + sp_dist2;
872:                 if (total_cost <= thresh) {
873:                     ru = merge_Select(ru, rv);
874:                 }
875:             }
876:         }
877:     }
878: 
879:     // Enforce minimum component size (min_cutoff) by merging small fragments into closest neighbor
880:     for (int iter = 0; iter < 3; ++iter) {
881:         for (int32_t i = 0; i < n_pts; ++i) {
882:             int32_t ru = find_root(i);
883:             if (comp_size[ru] >= min_cutoff) continue;
884: 
885:             const int deg = adj_counts[i];
886:             int32_t best_rv = -1;
887:             float best_cost = 1e30f;
888:             for (int k = 0; k < deg; ++k) {
889:                 int32_t j = adj_indices[static_cast<size_t>(i) * MAX_K + k];
890:                 int32_t rv = find_root(j);
891:                 if (ru == rv) continue;
892: 
893:                 float feat_dist2 = 0.0f;
894:                 for (int d = 0; d < d_feat; ++d) {
895:                     float diff = comp_feat[static_cast<size_t>(ru) * d_feat + d] -
896:                                  comp_feat[static_cast<size_t>(rv) * d_feat + d];
897:                     feat_dist2 += diff * diff;
898:                 }
899:                 if (feat_dist2 < best_cost) {
900:                     best_cost = feat_dist2;
901:                     best_rv = rv;
902:                 }
903:             }
904:             if (best_rv != -1) {
905:                 merge_Select(ru, best_rv);
906:             }
907:         }
908:     }
909: 
910:     // Relabel components contiguously 0 .. num_sp - 1
911:     std::vector<int32_t> root_to_id(n_pts, -1);
912:     int32_t num_sp = 0;
913:     for (int32_t i = 0; i < n_pts; ++i) {
914:         int32_t r = find_root(i);
915:         if (root_to_id[r] == -1) {
916:             root_to_id[r] = num_sp++;
917:         }
918:         sp_labels_out[i] = root_to_id[r];
919:     }
920:     return num_sp;
921: }
922: 
923: // -----------------------------------------------------------------------------
924: // 5. Exact Superpoint Boundary Adjacency Graph Extraction
925: // Connects superpoints u and v if any constituent P0 points lie within adj_radius.
926: // Writes up to max_edges undirected edges (u < v) to edge_u_out and edge_v_out.
927: // -----------------------------------------------------------------------------
928: int32_t spt_build_superpoint_graph(
929:     const float* xyz,
930:     const int32_t* sp_labels,
931:     int32_t n_pts,
932:     int32_t num_sp,
933:     float adj_radius,
934:     int32_t max_edges,
935:     int32_t* edge_u_out,
936:     int32_t* edge_v_out
937: ) {
938:     if (n_pts <= 0 || num_sp <= 1) return 0;
939: 
940:     SpatialGrid grid;
941:     grid.build(xyz, n_pts, adj_radius);
942:     const float r2 = adj_radius * adj_radius;
943: 
944:     const int n_threads = omp_get_max_threads();
945:     std::vector<std::vector<uint64_t>> thread_edges(n_threads);
946: 
947:     #pragma omp parallel
948:     {
949:         const int tid = omp_get_thread_num();
950:         auto& local_vec = thread_edges[tid];
951:         local_vec.reserve(4096);
952: 
953:         #pragma omp for schedule(dynamic, 1024)
954:         for (int32_t i = 0; i < n_pts; ++i) {
955:             const int32_t sp_u = sp_labels[i];
956:             const float px = xyz[3 * i + 0];
957:             const float py = xyz[3 * i + 1];
958:             const float pz = xyz[3 * i + 2];
959:             int32_t ix, iy, iz;
960:             grid.point_to_cell(px, py, pz, ix, iy, iz);
961: 
962:             for (int32_t dz = -1; dz <= 1; ++dz) {
963:                 for (int32_t dy = -1; dy <= 1; ++dy) {
964:                     for (int32_t dx = -1; dx <= 1; ++dx) {
965:                         int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
966:                         if (cid == -1) continue;
967:                         const int32_t start = grid.point_start[cid];
968:                         const int32_t end = start + grid.point_count[cid];
969:                         for (int32_t k = start; k < end; ++k) {
970:                             int32_t j = grid.sorted_points[k];
971:                             int32_t sp_v = sp_labels[j];
972:                             if (sp_u >= sp_v) continue;
973:                             float qx = xyz[3 * j + 0] - px;
974:                             float qy = xyz[3 * j + 1] - py;
975:                             float qz = xyz[3 * j + 2] - pz;
976:                             if (qx * qx + qy * qy + qz * qz <= r2) {
977:                                 uint64_t key = (static_cast<uint64_t>(static_cast<uint32_t>(sp_u)) << 32ULL) |
978:                                                static_cast<uint64_t>(static_cast<uint32_t>(sp_v));
979:                                 local_vec.push_back(key);
980:                             }
981:                         }
982:                     }
983:                 }
984:             }
985:         }
986:         std::sort(local_vec.begin(), local_vec.end());
987:         local_vec.erase(std::unique(local_vec.begin(), local_vec.end()), local_vec.end());
988:     }
989: 
990:     std::vector<uint64_t> all_edges;
991:     for (int t = 0; t < n_threads; ++t) {
992:         all_edges.insert(all_edges.end(), thread_edges[t].begin(), thread_edges[t].end());
993:     }
994:     std::sort(all_edges.begin(), all_edges.end());
995:     all_edges.erase(std::unique(all_edges.begin(), all_edges.end()), all_edges.end());
996: 
997:     const int32_t count = std::min(static_cast<int32_t>(all_edges.size()), max_edges);
998:     for (int32_t e = 0; e < count; ++e) {
999:         edge_u_out[e] = static_cast<int32_t>(all_edges[e] >> 32ULL);
1000:         edge_v_out[e] = static_cast<int32_t>(all_edges[e] & 0xFFFFFFFFULL);
1001:     }
1002:     return count;
1003: }
1004: 
1005: // -----------------------------------------------------------------------------
1006: // 6. Fast Out-of-Core Mapping of Full-Resolution Point Chunks to Nearest P0 Voxel
1007: // Used during chunked streaming of 100M-300M+ point clouds to map P0 predictions
1008: // and normals back to full-resolution chunks in O(N_chunk) time and bounded RAM.
1009: // -----------------------------------------------------------------------------
1010: void spt_map_points_to_p0(
1011:     const float* p0_xyz,
1012:     int32_t num_p0,
1013:     const float* query_xyz,
1014:     int32_t n_query,
1015:     float voxel_size,
1016:     int32_t* query_to_p0_out
1017: ) {
1018:     if (num_p0 <= 0 || n_query <= 0) return;
1019: 
1020:     SpatialGrid grid;
1021:     grid.build(p0_xyz, num_p0, voxel_size * 1.8f);
1022: 
1023:     #pragma omp parallel for schedule(static)
1024:     for (int32_t i = 0; i < n_query; ++i) {
1025:         const float px = query_xyz[3 * i + 0];
1026:         const float py = query_xyz[3 * i + 1];
1027:         const float pz = query_xyz[3 * i + 2];
1028:         int32_t ix, iy, iz;
1029:         grid.point_to_cell(px, py, pz, ix, iy, iz);
1030: 
1031:         int32_t best_j = 0;
1032:         float best_d2 = 1e30f;
1033: 
1034:         for (int32_t dz = -1; dz <= 1; ++dz) {
1035:             for (int32_t dy = -1; dy <= 1; ++dy) {
1036:                 for (int32_t dx = -1; dx <= 1; ++dx) {
1037:                     int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
1038:                     if (cid == -1) continue;
1039:                     const int32_t start = grid.point_start[cid];
1040:                     const int32_t end = start + grid.point_count[cid];
1041:                     for (int32_t k = start; k < end; ++k) {
1042:                         int32_t j = grid.sorted_points[k];
1043:                         float dx_ = p0_xyz[3 * j + 0] - px;
1044:                         float dy_ = p0_xyz[3 * j + 1] - py;
1045:                         float dz_ = p0_xyz[3 * j + 2] - pz;
1046:                         float d2 = dx_ * dx_ + dy_ * dy_ + dz_ * dz_;
1047:                         if (d2 < best_d2) {
1048:                             best_d2 = d2;
1049:                             best_j = j;
1050:                         }
1051:                     }
1052:                 }
1053:             }
1054:         }
1055:         query_to_p0_out[i] = best_j;
1056:     }
1057: }
1058: 
1059: // -----------------------------------------------------------------------------
1060: // 7. CUDA-Accelerated WNNC Global Normal Estimation (Lin et al., ACM ToG 2024)
1061: // Uses WindingNumberOperator<float> + wnnc::estimateNormals to compute globally
1062: // consistent normals across the cave point cloud.
1063: // Negates outward WNNC dipole normals so interior cave normals point INWARD:
1064: //   - Cave Ceiling : nz < 0 (pointing downward into the cavity)
1065: //   - Cave Floor   : nz > 0 (pointing upward into the cavity)
1066: //   - Cave Walls   : |nz| ~ 0 (pointing horizontally into the cavity)
1067: // For massive P0 clouds (n_pts > max_wnnc_pts), solves WNNC on a uniform carrier
1068: // cloud of ~max_wnnc_pts points and propagates/interpolates to all P0 points.
1069: // -----------------------------------------------------------------------------
1070: void spt_compute_wnnc_normals(
1071:     const float* xyz,
1072:     int32_t n_pts,
1073:     int32_t iterations,
1074:     float width_min,
1075:     float width_max,
1076:     int32_t max_wnnc_pts,
1077:     float* normals_out
1078: ) {
1079:     if (n_pts <= 0) return;
1080: 
1081:     auto run_wnnc_direct = [&](const float* pts_in, int32_t count, float* nrm_out) {
1082:         float min_x = pts_in[0], min_y = pts_in[1], min_z = pts_in[2];
1083:         float max_x = min_x, max_y = min_y, max_z = min_z;
1084:         for (int32_t i = 1; i < count; ++i) {
1085:             min_x = std::min(min_x, pts_in[3 * i + 0]);
1086:             min_y = std::min(min_y, pts_in[3 * i + 1]);
1087:             min_z = std::min(min_z, pts_in[3 * i + 2]);
1088:             max_x = std::max(max_x, pts_in[3 * i + 0]);
1089:             max_y = std::max(max_y, pts_in[3 * i + 1]);
1090:             max_z = std::max(max_z, pts_in[3 * i + 2]);
1091:         }
1092:         const float cx = 0.5f * (min_x + max_x);
1093:         const float cy = 0.5f * (min_y + max_y);
1094:         const float cz = 0.5f * (min_z + max_z);
1095:         const float longest = std::max({max_x - min_x, max_y - min_y, max_z - min_z, 1e-6f});
1096:         const float scale = 2.0f / (longest * 1.1f);
1097: 
1098:         std::vector<wnnc::Vec3<float>> norm_pts(count);
1099:         #pragma omp parallel for schedule(static)
1100:         for (int32_t i = 0; i < count; ++i) {
1101:             norm_pts[i] = {
1102:                 (pts_in[3 * i + 0] - cx) * scale,
1103:                 (pts_in[3 * i + 1] - cy) * scale,
1104:                 (pts_in[3 * i + 2] - cz) * scale
1105:             };
1106:         }
1107: 
1108:         wnnc::WindingNumberOperator<float> wn_op(std::move(norm_pts), 15, 4);
1109:         wnnc::SolverSettings settings;
1110:         settings.iterations = iterations;
1111:         settings.widthMin = width_min;
1112:         settings.widthMax = width_max;
1113: 
1114:         std::vector<wnnc::Vec3<float>> wn_normals = wnnc::estimateNormals(wn_op, settings);
1115: 
1116:         // Negate outward WNNC normal so cave normals point inward into the cavity
1117:         // (Ceiling: nz < 0, Floor: nz > 0)
1118:         #pragma omp parallel for schedule(static)
1119:         for (int32_t i = 0; i < count; ++i) {
1120:             nrm_out[3 * i + 0] = -wn_normals[i].x;
1121:             nrm_out[3 * i + 1] = -wn_normals[i].y;
1122:             nrm_out[3 * i + 2] = -wn_normals[i].z;
1123:         }
1124:     };
1125: 
1126:     if (n_pts <= max_wnnc_pts) {
1127:         run_wnnc_direct(xyz, n_pts, normals_out);
1128:         return;
1129:     }
1130: 
1131:     // Subsample a uniform carrier grid targeting ~max_wnnc_pts points
1132:     float min_x = xyz[0], min_y = xyz[1], min_z = xyz[2];
1133:     float max_x = min_x, max_y = min_y, max_z = min_z;
1134:     for (int32_t i = 1; i < n_pts; ++i) {
1135:         min_x = std::min(min_x, xyz[3 * i + 0]);
1136:         min_y = std::min(min_y, xyz[3 * i + 1]);
1137:         min_z = std::min(min_z, xyz[3 * i + 2]);
1138:         max_x = std::max(max_x, xyz[3 * i + 0]);
1139:         max_y = std::max(max_y, xyz[3 * i + 1]);
1140:         max_z = std::max(max_z, xyz[3 * i + 2]);
1141:     }
1142:     const float diag = std::hypot(max_x - min_x, std::hypot(max_y - min_y, max_z - min_z));
1143:     float carrier_voxel = std::max(0.08f, diag / 900.0f);
1144: 
1145:     SpatialGrid cgrid;
1146:     cgrid.build(xyz, n_pts, carrier_voxel);
1147:     while (static_cast<int32_t>(cgrid.point_count.size()) > max_wnnc_pts) {
1148:         carrier_voxel *= 1.25f;
1149:         cgrid.build(xyz, n_pts, carrier_voxel);
1150:     }
1151: 
1152:     const int32_t n_carr = static_cast<int32_t>(cgrid.point_count.size());
1153:     std::vector<float> carr_xyz(static_cast<size_t>(n_carr) * 3);
1154:     std::vector<float> carr_nrm(static_cast<size_t>(n_carr) * 3);
1155: 
1156:     #pragma omp parallel for schedule(static)
1157:     for (int32_t c = 0; c < n_carr; ++c) {
1158:         const int32_t start = cgrid.point_start[c];
1159:         const int32_t count = cgrid.point_count[c];
1160:         double cx = 0.0, cy = 0.0, cz = 0.0;
1161:         for (int32_t k = 0; k < count; ++k) {
1162:             int32_t idx = cgrid.sorted_points[start + k];
1163:             cx += xyz[3 * idx + 0];
1164:             cy += xyz[3 * idx + 1];
1165:             cz += xyz[3 * idx + 2];
1166:         }
1167:         carr_xyz[3 * c + 0] = static_cast<float>(cx / count);
1168:         carr_xyz[3 * c + 1] = static_cast<float>(cy / count);
1169:         carr_xyz[3 * c + 2] = static_cast<float>(cz / count);
1170:     }
1171: 
1172:     run_wnnc_direct(carr_xyz.data(), n_carr, carr_nrm.data());
1173: 
1174:     // Smoothly interpolate WNNC carrier normals to all P0 points via inverse-distance weighting
1175:     SpatialGrid ngrid;
1176:     ngrid.build(carr_xyz.data(), n_carr, carrier_voxel * 1.6f);
1177: 
1178:     #pragma omp parallel for schedule(static)
1179:     for (int32_t i = 0; i < n_pts; ++i) {
1180:         const float px = xyz[3 * i + 0];
1181:         const float py = xyz[3 * i + 1];
1182:         const float pz = xyz[3 * i + 2];
1183:         int32_t ix, iy, iz;
1184:         ngrid.point_to_cell(px, py, pz, ix, iy, iz);
1185: 
1186:         Eigen::Vector3f acc(0.0f, 0.0f, 0.0f);
1187:         int32_t best_j = 0;
1188:         float best_d2 = 1e30f;
1189: 
1190:         for (int32_t dz = -1; dz <= 1; ++dz) {
1191:             for (int32_t dy = -1; dy <= 1; ++dy) {
1192:                 for (int32_t dx = -1; dx <= 1; ++dx) {
1193:                     int32_t cid = ngrid.find_cell(ix + dx, iy + dy, iz + dz);
