--- /home/projval/Documents/cgal/src/spt_filter/spt_kernels.cpp
+++ /home/projval/Documents/cgal/src/spt_filter/spt_kernels.cpp
@@ ... @@
-void spt_compute_scale_features(
    const float* xyz,
    float* normals_inout,
    int32_t n_pts,
    float radius,
    int32_t compute_normals,
    float* feat_out
) {
    // For coarse scales (radius >= 0.30m) on large clouds when normals are already known,
    // subsample a uniform carrier grid (cell_size = radius * 0.22f, e.g. 11cm for r=0.50m)
    // so each 0.50m sphere contains ~60 uniform carrier points instead of 500+ dense P0 points.
    std::vector<float> carrier_xyz;
    std::vector<float> carrier_normals;
    const float* search_xyz = xyz;
    const float* search_normals = normals_inout;
    int32_t n_search = n_pts;

    if (compute_normals == 0 && radius >= 0.30f && n_pts > 50000) {
        const float carrier_cell = radius * 0.22f;
        SpatialGrid cgrid;
        cgrid.build(xyz, n_pts, carrier_cell);
        const int32_t n_carr = static_cast<int32_t>(cgrid.point_count.size());
        carrier_xyz.resize(static_cast<size_t>(n_carr) * 3);
        carrier_normals.resize(static_cast<size_t>(n_carr) * 3);

        #pragma omp parallel for schedule(static)
        for (int32_t c = 0; c < n_carr; ++c) {
            const int32_t start = cgrid.point_start[c];
            const int32_t count = cgrid.point_count[c];
            double cx = 0.0, cy = 0.0, cz = 0.0;
            for (int32_t k = 0; k < count; ++k) {
                int32_t idx = cgrid.sorted_points[start + k];
                cx += xyz[3 * idx + 0];
                cy += xyz[3 * idx + 1];
                cz += xyz[3 * idx + 2];
            }
            cx /= count;
            cy /= count;
            cz /= count;
            int32_t rep = cgrid.sorted_points[start];
            carrier_xyz[3 * c + 0] = static_cast<float>(cx);
            carrier_xyz[3 * c + 1] = static_cast<float>(cy);
            carrier_xyz[3 * c + 2] = static_cast<float>(cz);
            carrier_normals[3 * c + 0] = normals_inout[3 * rep + 0];
            carrier_normals[3 * c + 1] = normals_inout[3 * rep + 1];
            carrier_normals[3 * c + 2] = normals_inout[3 * rep + 2];
        }
        search_xyz = carrier_xyz.data();
        search_normals = carrier_normals.data();
        n_search = n_carr;
    }

    SpatialGrid grid;
    grid.build(search_xyz, n_search, radius);
    const float r2 = radius * radius;

    // Step A: If normals need to be estimated from PCA, compute unoriented PCA normals and fine eigenvalues first,
    // then orient using 2D-planar-surface XY column bounds (which naturally ignores 3D foliage & 1D trunks).
    if (compute_normals != 0) {
        #pragma omp parallel for schedule(dynamic, 1024)
        for (int32_t i = 0; i < n_pts; ++i) {
            const float px = xyz[3 * i + 0];
            const float py = xyz[3 * i + 1];
            const float pz = xyz[3 * i + 2];
            int32_t ix, iy, iz;
            grid.point_to_cell(px, py, pz, ix, iy, iz);

            double mx = 0.0, my = 0.0, mz = 0.0;
            double cxx = 0.0, cxy = 0.0, cxz = 0.0, cyy = 0.0, cyz = 0.0, czz = 0.0;
            int32_t cnt = 0;

            for (int32_t dz = -1; dz <= 1; ++dz) {
                for (int32_t dy = -1; dy <= 1; ++dy) {
                    for (int32_t dx = -1; dx <= 1; ++dx) {
                        int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                        if (cid == -1) continue;
                        const int32_t start = grid.point_start[cid];
                        const int32_t end = start + grid.point_count[cid];
                        for (int32_t k = start; k < end; ++k) {
                            int32_t j = grid.sorted_points[k];
                            float qx = search_xyz[3 * j + 0] - px;
                            float qy = search_xyz[3 * j + 1] - py;
                            float qz = search_xyz[3 * j + 2] - pz;
                            if (qx * qx + qy * qy + qz * qz <= r2) {
                                mx += qx; my += qy; mz += qz;
                                cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                                cnt++;
                            }
                        }
                    }
                }
            }

            Eigen::Vector3f n_vec(0.0f, 0.0f, 1.0f);
            if (cnt >= 4) {
                double inv_n = 1.0 / cnt;
                mx *= inv_n; my *= inv_n; mz *= inv_n;
                Eigen::Matrix3f cov;
                cov(0, 0) = static_cast<float>(cxx * inv_n - mx * mx);
                cov(0, 1) = cov(1, 0) = static_cast<float>(cxy * inv_n - mx * my);
                cov(0, 2) = cov(2, 0) = static_cast<float>(cxz * inv_n - mx * mz);
                cov(1, 1) = static_cast<float>(cyy * inv_n - my * my);
                cov(1, 2) = cov(2, 1) = static_cast<float>(cyz * inv_n - my * mz);
                cov(2, 2) = static_cast<float>(czz * inv_n - mz * mz);

                Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> es;
                es.computeDirect(cov);
                n_vec = es.eigenvectors().col(0);
                const float l3 = std::max(0.0f, es.eigenvalues()(0));
                const float l2 = std::max(l3, es.eigenvalues()(1));
                const float l1 = std::max(l2, es.eigenvalues()(2));
                const float sum_l = l1 + l2 + l3 + 1e-12f;
                const float l1_eps = l1 + 1e-12f;
                feat_out[6 * i + 0] = l3 / sum_l;
                feat_out[6 * i + 1] = (l2 - l3) / l1_eps;
                feat_out[6 * i + 2] = l3 / l1_eps;
                feat_out[6 * i + 3] = (l1 - l2) / l1_eps;
                feat_out[6 * i + 4] = std::cbrt(l1 * l2 * l3) / sum_l;
                feat_out[6 * i + 5] = 0.0f;
            } else {
                feat_out[6 * i + 0] = 0.33f;
                feat_out[6 * i + 1] = 0.0f;
                feat_out[6 * i + 2] = 1.0f;
                feat_out[6 * i + 3] = 0.0f;
                feat_out[6 * i + 4] = 0.33f;
                feat_out[6 * i + 5] = 0.8f;
            }
            normals_inout[3 * i + 0] = n_vec.x();
            normals_inout[3 * i + 1] = n_vec.y();
            normals_inout[3 * i + 2] = n_vec.z();
        }

        // Build 4.0m XY column bounds using ONLY non-vertical 2D planar surfaces
        // (|nz| > 0.35, rugosity < 0.065, planarity > 0.42), which excludes trees/bushes/trunks!
        SpatialGrid tunnel_grid;
        tunnel_grid.build(xyz, n_pts, 4.0f);
        const int32_t num_tcells = static_cast<int32_t>(tunnel_grid.point_count.size());

        // Precompute per-cell XY coordinate sums in O(n_pts) to avoid inner-loop scans over 4m cells
        std::vector<double> tcell_sum_x(num_tcells, 0.0);
        std::vector<double> tcell_sum_y(num_tcells, 0.0);

        struct ColBounds { float z_min; float z_max; int32_t planar_cnt; };
        std::unordered_map<uint64_t, ColBounds> xy_cols;
        xy_cols.reserve(num_tcells);

        for (int32_t c = 0; c < num_tcells; ++c) {
            uint64_t key = (static_cast<uint64_t>(static_cast<uint32_t>(tunnel_grid.cell_ix[c])) << 32ULL) |
                           static_cast<uint64_t>(static_cast<uint32_t>(tunnel_grid.cell_iy[c]));
            const int32_t start = tunnel_grid.point_start[c];
            const int32_t end = start + tunnel_grid.point_count[c];
            double sx = 0.0, sy = 0.0;
            for (int32_t k = start; k < end; ++k) {
                int32_t idx = tunnel_grid.sorted_points[k];
                sx += xyz[3 * idx + 0];
                sy += xyz[3 * idx + 1];
                float abs_nz = std::abs(normals_inout[3 * idx + 2]);
                if (abs_nz > 0.35f && feat_out[6 * idx + 0] < 0.065f && feat_out[6 * idx + 1] > 0.42f) {
                    float pz = xyz[3 * idx + 2];
                    auto it = xy_cols.find(key);
                    if (it == xy_cols.end()) {
                        xy_cols[key] = {pz, pz, 1};
                    } else {
                        it->second.z_min = std::min(it->second.z_min, pz);
                        it->second.z_max = std::max(it->second.z_max, pz);
                        it->second.planar_cnt++;
                    }
                }
            }
            tcell_sum_x[c] = sx;
            tcell_sum_y[c] = sy;
        }

        #pragma omp parallel for schedule(static)
        for (int32_t i = 0; i < n_pts; ++i) {
            const float px = xyz[3 * i + 0];
            const float py = xyz[3 * i + 1];
            const float pz = xyz[3 * i + 2];
            Eigen::Vector3f n_vec(normals_inout[3 * i + 0], normals_inout[3 * i + 1], normals_inout[3 * i + 2]);

            int32_t tix, tiy, tiz;
            tunnel_grid.point_to_cell(px, py, pz, tix, tiy, tiz);

            float col_zmin = 1e30f, col_zmax = -1e30f;
            int32_t p_cnt = 0;
            for (int32_t dy = -1; dy <= 1; ++dy) {
                for (int32_t dx = -1; dx <= 1; ++dx) {
                    uint64_t key = (static_cast<uint64_t>(static_cast<uint32_t>(tix + dx)) << 32ULL) |
                                   static_cast<uint64_t>(static_cast<uint32_t>(tiy + dy));
                    auto it = xy_cols.find(key);
                    if (it != xy_cols.end() && it->second.planar_cnt >= 5) {
                        col_zmin = std::min(col_zmin, it->second.z_min);
                        col_zmax = std::max(col_zmax, it->second.z_max);
                        p_cnt += it->second.planar_cnt;
                    }
                }
            }

            // Compute local 8m horizontal XY centroid in O(27) using precomputed cell sums
            double tx = 0.0, ty = 0.0;
            int32_t tcnt = 0;
            for (int32_t dz = -1; dz <= 1; ++dz) {
                for (int32_t dy = -1; dy <= 1; ++dy) {
                    for (int32_t dx = -1; dx <= 1; ++dx) {
                        int32_t cid = tunnel_grid.find_cell(tix + dx, tiy + dy, tiz + dz);
                        if (cid == -1) continue;
                        tx += tcell_sum_x[cid];
                        ty += tcell_sum_y[cid];
                        tcnt += tunnel_grid.point_count[cid];
                    }
                }
            }

            const float z_span = (p_cnt > 0) ? (col_zmax - col_zmin) : 0.0f;
            if (z_span < 1.6f) {
                // Single-layer horizontal surface (exterior ground): orient upward (+Z)
                if (n_vec.z() < 0.0f) n_vec = -n_vec;
            } else {
                // Multi-layer cave passage: ceiling is above mid_z (points down), floor is below mid_z (points up)
                float mid_z = 0.5f * (col_zmin + col_zmax);
                Eigen::Vector3f to_center(
                    tcnt > 0 ? static_cast<float>(tx / tcnt - px) : 0.0f,
                    tcnt > 0 ? static_cast<float>(ty / tcnt - py) : 0.0f,
                    mid_z - pz
                );
                if (n_vec.dot(to_center) < 0.0f) {
                    n_vec = -n_vec;
                }
            }
            normals_inout[3 * i + 0] = n_vec.x();
            normals_inout[3 * i + 1] = n_vec.y();
            normals_inout[3 * i + 2] = n_vec.z();
        }
    }

    // Step B: Compute eigenvalues (if compute_normals == 0) and sign-invariant normal structure tensor dispersion
    #pragma omp parallel for schedule(dynamic, 1024)
    for (int32_t i = 0; i < n_pts; ++i) {
        const float px = xyz[3 * i + 0];
        const float py = xyz[3 * i + 1];
        const float pz = xyz[3 * i + 2];
        int32_t ix, iy, iz;
        grid.point_to_cell(px, py, pz, ix, iy, iz);

        double mx = 0.0, my = 0.0, mz = 0.0;
        double cxx = 0.0, cxy = 0.0, cxz = 0.0, cyy = 0.0, cyz = 0.0, czz = 0.0;
        // Sign-invariant normal structure tensor T = (1/m) sum(n_j * n_j^T)
        double nxx = 0.0, nxy = 0.0, nxz = 0.0, nyy = 0.0, nyz = 0.0, nzz = 0.0;
        int32_t cnt = 0;

        for (int32_t dz = -1; dz <= 1; ++dz) {
            for (int32_t dy = -1; dy <= 1; ++dy) {
                for (int32_t dx = -1; dx <= 1; ++dx) {
                    int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                    if (cid == -1) continue;
                    const int32_t start = grid.point_start[cid];
                    const int32_t end = start + grid.point_count[cid];
                    for (int32_t k = start; k < end; ++k) {
                        int32_t j = grid.sorted_points[k];
                        float qx = search_xyz[3 * j + 0] - px;
                        float qy = search_xyz[3 * j + 1] - py;
                        float qz = search_xyz[3 * j + 2] - pz;
                        if (qx * qx + qy * qy + qz * qz <= r2) {
                            if (compute_normals == 0) {
                                mx += qx; my += qy; mz += qz;
                                cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                            }
                            float njx = search_normals[3 * j + 0];
                            float njy = search_normals[3 * j + 1];
                            float njz = search_normals[3 * j + 2];
                            nxx += njx * njx; nxy += njx * njy; nxz += njx * njz;
                            nyy += njy * njy; nyz += njy * njz; nzz += njz * njz;
                            cnt++;
                        }
                    }
                }
            }
        }

        if (cnt < 4) {
            if (compute_normals == 0) {
                feat_out[6 * i + 0] = 0.33f;
                feat_out[6 * i + 1] = 0.0f;
                feat_out[6 * i + 2] = 1.0f;
                feat_out[6 * i + 3] = 0.0f;
                feat_out[6 * i + 4] = 0.33f;
            }
            feat_out[6 * i + 5] = 0.8f;
            continue;
        }

        double inv_n = 1.0 / cnt;
        if (compute_normals == 0) {
            mx *= inv_n; my *= inv_n; mz *= inv_n;
            Eigen::Matrix3f cov;
            cov(0, 0) = static_cast<float>(cxx * inv_n - mx * mx);
            cov(0, 1) = cov(1, 0) = static_cast<float>(cxy * inv_n - mx * my);
            cov(0, 2) = cov(2, 0) = static_cast<float>(cxz * inv_n - mx * mz);
            cov(1, 1) = static_cast<float>(cyy * inv_n - my * my);
            cov(1, 2) = cov(2, 1) = static_cast<float>(cyz * inv_n - my * mz);
            cov(2, 2) = static_cast<float>(czz * inv_n - mz * mz);

            Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> es;
            es.computeDirect(cov, Eigen::EigenvaluesOnly);
            const float l3 = std::max(0.0f, es.eigenvalues()(0));
            const float l2 = std::max(l3, es.eigenvalues()(1));
            const float l1 = std::max(l2, es.eigenvalues()(2));
            const float sum_l = l1 + l2 + l3 + 1e-12f;
            const float l1_eps = l1 + 1e-12f;

            feat_out[6 * i + 0] = l3 / sum_l;
            feat_out[6 * i + 1] = (l2 - l3) / l1_eps;
            feat_out[6 * i + 2] = l3 / l1_eps;
            feat_out[6 * i + 3] = (l1 - l2) / l1_eps;
            feat_out[6 * i + 4] = std::cbrt(l1 * l2 * l3) / sum_l;
        }

        // Sign-invariant normal structure tensor largest eigenvalue mu_max in [1/3, 1]
        Eigen::Matrix3f n_cov;
        n_cov(0, 0) = static_cast<float>(nxx * inv_n);
        n_cov(0, 1) = n_cov(1, 0) = static_cast<float>(nxy * inv_n);
        n_cov(0, 2) = n_cov(2, 0) = static_cast<float>(nxz * inv_n);
        n_cov(1, 1) = static_cast<float>(nyy * inv_n);
        n_cov(1, 2) = n_cov(2, 1) = static_cast<float>(nyz * inv_n);
        n_cov(2, 2) = static_cast<float>(nzz * inv_n);

        Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> nes;
        nes.computeDirect(n_cov, Eigen::EigenvaluesOnly);
        const float mu_max = std::clamp(nes.eigenvalues()(2), 0.333333f, 1.0f);
        const float normal_dispersion = std::clamp(1.5f * (1.0f - mu_max), 0.0f, 1.0f);

        feat_out[6 * i + 5] = normal_dispersion;
    }
}

// -----------------------------------------------------------------------------
// 3. 3D Cone Enclosure & Cavern Roof/Floor Raycasting
// Computes 4 enclosure descriptors per point using coarse-scale features:
//   enclosure_out[i * 4 + 0] = upward_occlusion (fraction of +Z cone rays hitting any upper surface)
//   enclosure_out[i * 4 + 1] = upward_roof_occlusion (fraction hitting coherent rock roof/wall)
//   enclosure_out[i * 4 + 2] = downward_floor_occlusion (fraction of -Z cone rays hitting lower floor)
//   enclosure_out[i * 4 + 3] = cavern_enclosure_score (combined 3D tunnel/shaft enclosure in [0, 1])
// -----------------------------------------------------------------------------
void spt_compute_enclosure(
    const float* xyz,
    const float* normals,
    const float* coarse_features, // stride 6: [rug, plan, scat, lin, omni, ndisp] at r_coarse
    int32_t n_pts,
    float occ_cell_size,
    float max_range,
    float* enclosure_out
) {
    SpatialGrid grid;
    grid.build(xyz, n_pts, occ_cell_size);
    const int32_t num_cells = static_cast<int32_t>(grid.point_count.size());

    // Precompute per-cell mean normal Z, coarse normal dispersion, coarse rugosity, and coarse planarity
    std::vector<float> cell_mean_nz(num_cells, 0.0f);
    std::vector<float> cell_mean_disp(num_cells, 0.0f);
    std::vector<float> cell_mean_rug(num_cells, 0.0f);
    std::vector<float> cell_mean_plan(num_cells, 0.0f);

    #pragma omp parallel for schedule(static)
    for (int32_t c = 0; c < num_cells; ++c) {
        const int32_t start = grid.point_start[c];
        const int32_t count = grid.point_count[c];
        double snz = 0.0, sdisp = 0.0, srug = 0.0, splan = 0.0;
        for (int32_t k = 0; k < count; ++k) {
            int32_t idx = grid.sorted_points[start + k];
            snz += normals[3 * idx + 2];
            srug += coarse_features[6 * idx + 0];
            splan += coarse_features[6 * idx + 1];
            sdisp += coarse_features[6 * idx + 5];
        }
        cell_mean_nz[c] = static_cast<float>(snz / count);
        cell_mean_rug[c] = static_cast<float>(srug / count);
        cell_mean_plan[c] = static_cast<float>(splan / count);
        cell_mean_disp[c] = static_cast<float>(sdisp / count);
    }

    // Generate 32 Fibonacci directions inside a 55-degree cone around +Z
    constexpr int K_CONE = 32;
    Eigen::Vector3f up_dirs[K_CONE];
    Eigen::Vector3f down_dirs[K_CONE];
    const float cos_max = std::cos(55.0f * static_cast<float>(M_PI) / 180.0f);
    const float golden_angle = static_cast<float>(M_PI * (3.0 - std::sqrt(5.0)));
    for (int k = 0; k < K_CONE; ++k) {
        float t = (k + 0.5f) / K_CONE;
        float cos_theta = 1.0f - t * (1.0f - cos_max);
        float sin_theta = std::sqrt(std::max(0.0f, 1.0f - cos_theta * cos_theta));
        float phi = k * golden_angle;
        up_dirs[k] = Eigen::Vector3f(sin_theta * std::cos(phi), sin_theta * std::sin(phi), cos_theta);
        down_dirs[k] = Eigen::Vector3f(sin_theta * std::cos(phi), sin_theta * std::sin(phi), -cos_theta);
    }

    // Generate 16 horizontal azimuth directions in XY plane for lateral wall/shaft enclosure
    constexpr int K_LAT = 16;
    Eigen::Vector3f lat_dirs[K_LAT];
    for (int k = 0; k < K_LAT; ++k) {
        float phi = 2.0f * static_cast<float>(M_PI) * k / K_LAT;
        lat_dirs[k] = Eigen::Vector3f(std::cos(phi), std::sin(phi), 0.0f);
    }

    const int max_steps = std::max(4, static_cast<int>(std::ceil(max_range / occ_cell_size)));
    const int min_step = std::max(4, static_cast<int>(std::ceil(1.00f / occ_cell_size)));

    #pragma omp parallel for schedule(dynamic, 1024)
    for (int32_t i = 0; i < n_pts; ++i) {
        const float px = xyz[3 * i + 0];
        const float py = xyz[3 * i + 1];
        const float pz = xyz[3 * i + 2];
        const float nz = normals[3 * i + 2];
        const float self_rug = coarse_features[6 * i + 0];
        const float self_plan = coarse_features[6 * i + 1];
        const float self_scat = coarse_features[6 * i + 2];
        const float self_disp = coarse_features[6 * i + 5];
        // A 2D manifold rock surface (high planarity, low scattering/rugosity/dispersion)
        // Excludes both 3D foliage (high scat/disp) and 1D tree trunks (low planarity)!
        const float self_rock_coherence =
            std::clamp((self_plan - 0.25f) * 2.5f, 0.0f, 1.0f) *
            std::clamp(1.0f - (self_disp - 0.35f) * 2.5f, 0.0f, 1.0f) *
            std::clamp(1.0f - (self_scat - 0.25f) * 3.0f, 0.0f, 1.0f) *
            std::clamp(1.0f - (self_rug - 0.12f) * 8.0f, 0.0f, 1.0f);

        int up_hits = 0;
        float roof_weighted_hits = 0.0f;

        for (int k = 0; k < K_CONE; ++k) {
            const Eigen::Vector3f& d = up_dirs[k];
            for (int s = min_step; s <= max_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    up_hits++;
                    float c_disp = cell_mean_disp[cid];
                    float c_rug = cell_mean_rug[cid];
                    float c_plan = cell_mean_plan[cid];
                    float disp_w = std::clamp(1.0f - (c_disp - 0.35f) * 2.5f, 0.0f, 1.0f);
                    float rug_w = std::clamp(1.0f - (c_rug - 0.12f) * 8.0f, 0.0f, 1.0f);
                    float plan_w = std::clamp((c_plan - 0.25f) * 2.5f, 0.0f, 1.0f);
                    roof_weighted_hits += disp_w * rug_w * plan_w;
                    break;
                }
            }
        }

        int down_hits = 0;
        float down_rock_hits = 0.0f;
        for (int k = 0; k < K_CONE; ++k) {
            const Eigen::Vector3f& d = down_dirs[k];
            for (int s = min_step; s <= max_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    down_hits++;
                    float c_disp = cell_mean_disp[cid];
                    float c_rug = cell_mean_rug[cid];
                    float c_plan = cell_mean_plan[cid];
                    float disp_w = std::clamp(1.0f - (c_disp - 0.35f) * 2.5f, 0.0f, 1.0f);
                    float rug_w = std::clamp(1.0f - (c_rug - 0.12f) * 8.0f, 0.0f, 1.0f);
                    float plan_w = std::clamp((c_plan - 0.25f) * 2.5f, 0.0f, 1.0f);
                    down_rock_hits += disp_w * rug_w * plan_w;
                    break;
                }
            }
        }

        int lat_rock_hits = 0;
        const int max_lat_steps = std::min(max_steps, static_cast<int>(std::ceil(25.0f / occ_cell_size)));
        for (int k = 0; k < K_LAT; ++k) {
            const Eigen::Vector3f& d = lat_dirs[k];
            for (int s = min_step; s <= max_lat_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    if (cell_mean_disp[cid] < 0.38f && cell_mean_rug[cid] < 0.13f && cell_mean_plan[cid] > 0.32f) {
                        lat_rock_hits++;
                    }
                    break;
                }
            }
        }

        const float up_occ = static_cast<float>(up_hits) / K_CONE;
        const float roof_occ = roof_weighted_hits / K_CONE;
        const float down_occ = static_cast<float>(down_hits) / K_CONE;
        const float down_rock_occ = down_rock_hits / K_CONE;
        const float lat_occ = static_cast<float>(lat_rock_hits) / K_LAT;

        // Combined 3D cavern enclosure score:
        // 1. Floor / lower walls / internal speleothems: covered by a coherent rock ceiling (roof_occ)
        // 2. Overhanging ceiling vaults (nz < -0.10): 2D rock surface with floor below or lateral walls
        // 3. Vertical shafts / fissures: 2D rock walls enclosed laterally (lat_occ >= 0.50) and vertically
        float ceiling_vault_score = 0.0f;
        if (nz < -0.10f) {
            float overhang_strength = std::clamp((-nz - 0.10f) / 0.40f, 0.0f, 1.0f);
            ceiling_vault_score = self_rock_coherence * overhang_strength *
                                  std::max(down_rock_occ, 0.7f * lat_occ);
        }
        float shaft_wall_score = self_rock_coherence * (
            std::sqrt(roof_occ * down_rock_occ) * 1.5f +
            0.70f * lat_occ * std::max({roof_occ, (lat_occ >= 0.50f ? down_rock_occ : 0.0f)})
        );

        float cavern_enclosure = std::clamp(
            std::max({roof_occ, ceiling_vault_score, shaft_wall_score}), 0.0f, 1.0f
        );

        enclosure_out[4 * i + 0] = up_occ;
        enclosure_out[4 * i + 1] = roof_occ;
        enclosure_out[4 * i + 2] = down_occ;
        enclosure_out[4 * i + 3] = cavern_enclosure;
    }
}
+void spt_compute_scale_features(
    const float* xyz,
    float* normals_inout,
    int32_t n_pts,
    float radius,
    int32_t compute_normals,
    float* feat_out
) {
    // For coarse scales (radius >= 0.30m) on large clouds when normals are already known,
    // subsample a uniform carrier grid (cell_size = radius * 0.22f, e.g. 11cm for r=0.50m)
    // so each 0.50m sphere contains ~60 uniform carrier points instead of 500+ dense P0 points.
    std::vector<float> carrier_xyz;
    std::vector<float> carrier_normals;
    const float* search_xyz = xyz;
    const float* search_normals = normals_inout;
    int32_t n_search = n_pts;

    if (compute_normals == 0 && radius >= 0.30f && n_pts > 50000) {
        const float carrier_cell = radius * 0.22f;
        SpatialGrid cgrid;
        cgrid.build(xyz, n_pts, carrier_cell);
        const int32_t n_carr = static_cast<int32_t>(cgrid.point_count.size());
        carrier_xyz.resize(static_cast<size_t>(n_carr) * 3);
        carrier_normals.resize(static_cast<size_t>(n_carr) * 3);

        #pragma omp parallel for schedule(static)
        for (int32_t c = 0; c < n_carr; ++c) {
            const int32_t start = cgrid.point_start[c];
            const int32_t count = cgrid.point_count[c];
            double cx = 0.0, cy = 0.0, cz = 0.0;
            for (int32_t k = 0; k < count; ++k) {
                int32_t idx = cgrid.sorted_points[start + k];
                cx += xyz[3 * idx + 0];
                cy += xyz[3 * idx + 1];
                cz += xyz[3 * idx + 2];
            }
            cx /= count;
            cy /= count;
            cz /= count;
            int32_t rep = cgrid.sorted_points[start];
            carrier_xyz[3 * c + 0] = static_cast<float>(cx);
            carrier_xyz[3 * c + 1] = static_cast<float>(cy);
            carrier_xyz[3 * c + 2] = static_cast<float>(cz);
            carrier_normals[3 * c + 0] = normals_inout[3 * rep + 0];
            carrier_normals[3 * c + 1] = normals_inout[3 * rep + 1];
            carrier_normals[3 * c + 2] = normals_inout[3 * rep + 2];
        }
        search_xyz = carrier_xyz.data();
        search_normals = carrier_normals.data();
        n_search = n_carr;
    }

    SpatialGrid grid;
    grid.build(search_xyz, n_search, radius);
    const float r2 = radius * radius;
    const float r2_expand = (2.0f * radius) * (2.0f * radius);

    // Step A: When compute_normals != 0, compute local PCA eigenvalues and eigenvectors,
    // and orient/blend with the global WNNC normals already provided in normals_inout.
    // We also keep pure local PCA directions in pca_dirs for sharp normal_dispersion computation.
    std::vector<float> pca_dirs;
    if (compute_normals != 0) {
        pca_dirs.resize(static_cast<size_t>(n_pts) * 3);

        #pragma omp parallel for schedule(dynamic, 1024)
        for (int32_t i = 0; i < n_pts; ++i) {
            const float px = xyz[3 * i + 0];
            const float py = xyz[3 * i + 1];
            const float pz = xyz[3 * i + 2];
            int32_t ix, iy, iz;
            grid.point_to_cell(px, py, pz, ix, iy, iz);

            double mx = 0.0, my = 0.0, mz = 0.0;
            double cxx = 0.0, cxy = 0.0, cxz = 0.0, cyy = 0.0, cyz = 0.0, czz = 0.0;
            int32_t cnt = 0;

            for (int32_t dz = -1; dz <= 1; ++dz) {
                for (int32_t dy = -1; dy <= 1; ++dy) {
                    for (int32_t dx = -1; dx <= 1; ++dx) {
                        int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                        if (cid == -1) continue;
                        const int32_t start = grid.point_start[cid];
                        const int32_t end = start + grid.point_count[cid];
                        for (int32_t k = start; k < end; ++k) {
                            int32_t j = grid.sorted_points[k];
                            float qx = search_xyz[3 * j + 0] - px;
                            float qy = search_xyz[3 * j + 1] - py;
                            float qz = search_xyz[3 * j + 2] - pz;
                            if (qx * qx + qy * qy + qz * qz <= r2) {
                                mx += qx; my += qy; mz += qz;
                                cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                                cnt++;
                            }
                        }
                    }
                }
            }

            // If point is in a low-density cave vault/wall (< 6 neighbors within r), expand search to 2*r
            if (cnt < 6) {
                mx = my = mz = 0.0;
                cxx = cxy = cxz = cyy = cyz = czz = 0.0;
                cnt = 0;
                for (int32_t dz = -2; dz <= 2; ++dz) {
                    for (int32_t dy = -2; dy <= 2; ++dy) {
                        for (int32_t dx = -2; dx <= 2; ++dx) {
                            int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                            if (cid == -1) continue;
                            const int32_t start = grid.point_start[cid];
                            const int32_t end = start + grid.point_count[cid];
                            for (int32_t k = start; k < end; ++k) {
                                int32_t j = grid.sorted_points[k];
                                float qx = search_xyz[3 * j + 0] - px;
                                float qy = search_xyz[3 * j + 1] - py;
                                float qz = search_xyz[3 * j + 2] - pz;
                                if (qx * qx + qy * qy + qz * qz <= r2_expand) {
                                    mx += qx; my += qy; mz += qz;
                                    cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                    cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                                    cnt++;
                                }
                            }
                        }
                    }
                }
            }

            Eigen::Vector3f wnnc_n(normals_inout[3 * i + 0], normals_inout[3 * i + 1], normals_inout[3 * i + 2]);
            float wnnc_norm = wnnc_n.norm();
            if (wnnc_norm > 1e-6f) {
                wnnc_n /= wnnc_norm;
            } else {
                wnnc_n = Eigen::Vector3f(0.0f, 0.0f, 1.0f);
            }

            Eigen::Vector3f n_vec = wnnc_n;
            if (cnt >= 4) {
                double inv_n = 1.0 / cnt;
                mx *= inv_n; my *= inv_n; mz *= inv_n;
                Eigen::Matrix3f cov;
                cov(0, 0) = static_cast<float>(cxx * inv_n - mx * mx);
                cov(0, 1) = cov(1, 0) = static_cast<float>(cxy * inv_n - mx * my);
                cov(0, 2) = cov(2, 0) = static_cast<float>(cxz * inv_n - mx * mz);
                cov(1, 1) = static_cast<float>(cyy * inv_n - my * my);
                cov(1, 2) = cov(2, 1) = static_cast<float>(cyz * inv_n - my * mz);
                cov(2, 2) = static_cast<float>(czz * inv_n - mz * mz);

                Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> es;
                es.computeDirect(cov);
                n_vec = es.eigenvectors().col(0);
                if (n_vec.dot(wnnc_n) < 0.0f) {
                    n_vec = -n_vec;
                }
                const float l3 = std::max(0.0f, es.eigenvalues()(0));
                const float l2 = std::max(l3, es.eigenvalues()(1));
                const float l1 = std::max(l2, es.eigenvalues()(2));
                const float sum_l = l1 + l2 + l3 + 1e-12f;
                const float l1_eps = l1 + 1e-12f;
                feat_out[6 * i + 0] = l3 / sum_l;
                feat_out[6 * i + 1] = (l2 - l3) / l1_eps;
                feat_out[6 * i + 2] = l3 / l1_eps;
                feat_out[6 * i + 3] = (l1 - l2) / l1_eps;
                feat_out[6 * i + 4] = std::cbrt(l1 * l2 * l3) / sum_l;
                feat_out[6 * i + 5] = 0.0f;
            } else {
                // Neutral low-entropy rock fallback for isolated/ultra-sparse points (never flag as vegetation)
                feat_out[6 * i + 0] = 0.03f;
                feat_out[6 * i + 1] = 0.65f;
                feat_out[6 * i + 2] = 0.08f;
                feat_out[6 * i + 3] = 0.15f;
                feat_out[6 * i + 4] = 0.12f;
                feat_out[6 * i + 5] = 0.08f;
            }
            pca_dirs[3 * i + 0] = n_vec.x();
            pca_dirs[3 * i + 1] = n_vec.y();
            pca_dirs[3 * i + 2] = n_vec.z();

            // Combine global WNNC orientation with local PCA normal
            Eigen::Vector3f blended = 0.60f * wnnc_n + 0.40f * n_vec;
            float b_norm = blended.norm();
            if (b_norm > 1e-6f) blended /= b_norm;
            else blended = wnnc_n;

            normals_inout[3 * i + 0] = blended.x();
            normals_inout[3 * i + 1] = blended.y();
            normals_inout[3 * i + 2] = blended.z();
        }
        search_normals = pca_dirs.data();
    }

    // Step B: Compute eigenvalues (if compute_normals == 0) and sign-invariant normal structure tensor dispersion
    #pragma omp parallel for schedule(dynamic, 1024)
    for (int32_t i = 0; i < n_pts; ++i) {
        const float px = xyz[3 * i + 0];
        const float py = xyz[3 * i + 1];
        const float pz = xyz[3 * i + 2];
        int32_t ix, iy, iz;
        grid.point_to_cell(px, py, pz, ix, iy, iz);

        double mx = 0.0, my = 0.0, mz = 0.0;
        double cxx = 0.0, cxy = 0.0, cxz = 0.0, cyy = 0.0, cyz = 0.0, czz = 0.0;
        // Sign-invariant normal structure tensor T = (1/m) sum(n_j * n_j^T)
        double nxx = 0.0, nxy = 0.0, nxz = 0.0, nyy = 0.0, nyz = 0.0, nzz = 0.0;
        int32_t cnt = 0;

        for (int32_t dz = -1; dz <= 1; ++dz) {
            for (int32_t dy = -1; dy <= 1; ++dy) {
                for (int32_t dx = -1; dx <= 1; ++dx) {
                    int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                    if (cid == -1) continue;
                    const int32_t start = grid.point_start[cid];
                    const int32_t end = start + grid.point_count[cid];
                    for (int32_t k = start; k < end; ++k) {
                        int32_t j = grid.sorted_points[k];
                        float qx = search_xyz[3 * j + 0] - px;
                        float qy = search_xyz[3 * j + 1] - py;
                        float qz = search_xyz[3 * j + 2] - pz;
                        if (qx * qx + qy * qy + qz * qz <= r2) {
                            if (compute_normals == 0) {
                                mx += qx; my += qy; mz += qz;
                                cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                            }
                            float njx = search_normals[3 * j + 0];
                            float njy = search_normals[3 * j + 1];
                            float njz = search_normals[3 * j + 2];
                            nxx += njx * njx; nxy += njx * njy; nxz += njx * njz;
                            nyy += njy * njy; nyz += njy * njz; nzz += njz * njz;
                            cnt++;
                        }
                    }
                }
            }
        }

        if (cnt < 6) {
            mx = my = mz = 0.0;
            cxx = cxy = cxz = cyy = cyz = czz = 0.0;
            nxx = nxy = nxz = nyy = nyz = nzz = 0.0;
            cnt = 0;
            for (int32_t dz = -2; dz <= 2; ++dz) {
                for (int32_t dy = -2; dy <= 2; ++dy) {
                    for (int32_t dx = -2; dx <= 2; ++dx) {
                        int32_t cid = grid.find_cell(ix + dx, iy + dy, iz + dz);
                        if (cid == -1) continue;
                        const int32_t start = grid.point_start[cid];
                        const int32_t end = start + grid.point_count[cid];
                        for (int32_t k = start; k < end; ++k) {
                            int32_t j = grid.sorted_points[k];
                            float qx = search_xyz[3 * j + 0] - px;
                            float qy = search_xyz[3 * j + 1] - py;
                            float qz = search_xyz[3 * j + 2] - pz;
                            if (qx * qx + qy * qy + qz * qz <= r2_expand) {
                                if (compute_normals == 0) {
                                    mx += qx; my += qy; mz += qz;
                                    cxx += qx * qx; cxy += qx * qy; cxz += qx * qz;
                                    cyy += qy * qy; cyz += qy * qz; czz += qz * qz;
                                }
                                float njx = search_normals[3 * j + 0];
                                float njy = search_normals[3 * j + 1];
                                float njz = search_normals[3 * j + 2];
                                nxx += njx * njx; nxy += njx * njy; nxz += njx * njz;
                                nyy += njy * njy; nyz += njy * njz; nzz += njz * njz;
                                cnt++;
                            }
                        }
                    }
                }
            }
        }

        if (cnt < 4) {
            if (compute_normals == 0) {
                feat_out[6 * i + 0] = 0.03f;
                feat_out[6 * i + 1] = 0.65f;
                feat_out[6 * i + 2] = 0.08f;
                feat_out[6 * i + 3] = 0.15f;
                feat_out[6 * i + 4] = 0.12f;
            }
            feat_out[6 * i + 5] = 0.08f;
            continue;
        }

        double inv_n = 1.0 / cnt;
        if (compute_normals == 0) {
            mx *= inv_n; my *= inv_n; mz *= inv_n;
            Eigen::Matrix3f cov;
            cov(0, 0) = static_cast<float>(cxx * inv_n - mx * mx);
            cov(0, 1) = cov(1, 0) = static_cast<float>(cxy * inv_n - mx * my);
            cov(0, 2) = cov(2, 0) = static_cast<float>(cxz * inv_n - mx * mz);
            cov(1, 1) = static_cast<float>(cyy * inv_n - my * my);
            cov(1, 2) = cov(2, 1) = static_cast<float>(cyz * inv_n - my * mz);
            cov(2, 2) = static_cast<float>(czz * inv_n - mz * mz);

            Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> es;
            es.computeDirect(cov, Eigen::EigenvaluesOnly);
            const float l3 = std::max(0.0f, es.eigenvalues()(0));
            const float l2 = std::max(l3, es.eigenvalues()(1));
            const float l1 = std::max(l2, es.eigenvalues()(2));
            const float sum_l = l1 + l2 + l3 + 1e-12f;
            const float l1_eps = l1 + 1e-12f;

            feat_out[6 * i + 0] = l3 / sum_l;
            feat_out[6 * i + 1] = (l2 - l3) / l1_eps;
            feat_out[6 * i + 2] = l3 / l1_eps;
            feat_out[6 * i + 3] = (l1 - l2) / l1_eps;
            feat_out[6 * i + 4] = std::cbrt(l1 * l2 * l3) / sum_l;
        }

        // Sign-invariant normal structure tensor largest eigenvalue mu_max in [1/3, 1]
        Eigen::Matrix3f n_cov;
        n_cov(0, 0) = static_cast<float>(nxx * inv_n);
        n_cov(0, 1) = n_cov(1, 0) = static_cast<float>(nxy * inv_n);
        n_cov(0, 2) = n_cov(2, 0) = static_cast<float>(nxz * inv_n);
        n_cov(1, 1) = static_cast<float>(nyy * inv_n);
        n_cov(1, 2) = n_cov(2, 1) = static_cast<float>(nyz * inv_n);
        n_cov(2, 2) = static_cast<float>(nzz * inv_n);

        Eigen::SelfAdjointEigenSolver<Eigen::Matrix3f> nes;
        nes.computeDirect(n_cov, Eigen::EigenvaluesOnly);
        const float mu_max = std::clamp(nes.eigenvalues()(2), 0.333333f, 1.0f);
        const float normal_dispersion = std::clamp(1.5f * (1.0f - mu_max), 0.0f, 1.0f);

        feat_out[6 * i + 5] = normal_dispersion;
    }
}

// -----------------------------------------------------------------------------
// 3. 3D Cone Enclosure & Cavern Roof/Floor Raycasting + Physical Normal Verification
// Computes 4 enclosure descriptors per point and enforces physical Floor/Ceiling
// normal consistency (Floor: nz > 0 when enclosed from above; Ceiling: nz < 0 when
// enclosed from below):
//   enclosure_out[i * 4 + 0] = upward_occlusion (fraction of +Z cone rays hitting any upper surface)
//   enclosure_out[i * 4 + 1] = upward_roof_occlusion (fraction hitting coherent rock roof/wall)
//   enclosure_out[i * 4 + 2] = downward_floor_occlusion (fraction of -Z cone rays hitting lower floor)
//   enclosure_out[i * 4 + 3] = cavern_enclosure_score (combined 3D tunnel/shaft enclosure in [0, 1])
// -----------------------------------------------------------------------------
void spt_compute_enclosure(
    const float* xyz,
    float* normals_inout,
    const float* fine_features,   // stride 6: [rug, plan, scat, lin, omni, ndisp] at r_fine
    const float* coarse_features, // stride 6: [rug, plan, scat, lin, omni, ndisp] at r_coarse
    int32_t n_pts,
    float occ_cell_size,
    float max_range,
    float* enclosure_out
) {
    SpatialGrid grid;
    grid.build(xyz, n_pts, occ_cell_size);
    const int32_t num_cells = static_cast<int32_t>(grid.point_count.size());

    // Precompute per-cell rock surface weight using fine & coarse features so rough/curved
    // karst ceilings count as solid roofs (rock_w ~ 1.0) while porous 3D leaf canopies are penalized.
    std::vector<float> cell_rock_weight(num_cells, 0.0f);

    #pragma omp parallel for schedule(static)
    for (int32_t c = 0; c < num_cells; ++c) {
        const int32_t start = grid.point_start[c];
        const int32_t count = grid.point_count[c];
        double f_rug = 0.0, f_plan = 0.0, f_scat = 0.0, f_disp = 0.0;
        double c_rug = 0.0, c_plan = 0.0;
        for (int32_t k = 0; k < count; ++k) {
            int32_t idx = grid.sorted_points[start + k];
            f_rug  += fine_features[6 * idx + 0];
            f_plan += fine_features[6 * idx + 1];
            f_scat += fine_features[6 * idx + 2];
            f_disp += fine_features[6 * idx + 5];
            c_rug  += coarse_features[6 * idx + 0];
            c_plan += coarse_features[6 * idx + 1];
        }
        f_rug  /= count;
        f_plan /= count;
        f_scat /= count;
        f_disp /= count;
        c_rug  /= count;
        c_plan /= count;

        float disp_w = std::clamp(1.0f - static_cast<float>(f_disp - 0.42) * 2.5f, 0.0f, 1.0f);
        float scat_w = std::clamp(1.0f - static_cast<float>(f_scat - 0.34) * 2.5f, 0.0f, 1.0f);
        float rug_w  = std::clamp(1.0f - static_cast<float>(f_rug  - 0.16) * 6.0f, 0.0f, 1.0f);
        float plan_w = std::clamp(static_cast<float>(std::max(f_plan, c_plan) - 0.18) * 3.0f, 0.25f, 1.0f);
        cell_rock_weight[c] = std::clamp(std::max(disp_w * scat_w * rug_w, disp_w * plan_w), 0.0f, 1.0f);
    }

    // Generate 32 Fibonacci directions inside a 55-degree cone around +Z
    constexpr int K_CONE = 32;
    Eigen::Vector3f up_dirs[K_CONE];
    Eigen::Vector3f down_dirs[K_CONE];
    const float cos_max = std::cos(55.0f * static_cast<float>(M_PI) / 180.0f);
    const float golden_angle = static_cast<float>(M_PI * (3.0 - std::sqrt(5.0)));
    for (int k = 0; k < K_CONE; ++k) {
        float t = (k + 0.5f) / K_CONE;
        float cos_theta = 1.0f - t * (1.0f - cos_max);
        float sin_theta = std::sqrt(std::max(0.0f, 1.0f - cos_theta * cos_theta));
        float phi = k * golden_angle;
        up_dirs[k] = Eigen::Vector3f(sin_theta * std::cos(phi), sin_theta * std::sin(phi), cos_theta);
        down_dirs[k] = Eigen::Vector3f(sin_theta * std::cos(phi), sin_theta * std::sin(phi), -cos_theta);
    }

    // Generate 16 horizontal azimuth directions in XY plane for lateral wall/shaft enclosure
    constexpr int K_LAT = 16;
    Eigen::Vector3f lat_dirs[K_LAT];
    for (int k = 0; k < K_LAT; ++k) {
        float phi = 2.0f * static_cast<float>(M_PI) * k / K_LAT;
        lat_dirs[k] = Eigen::Vector3f(std::cos(phi), std::sin(phi), 0.0f);
    }

    const int max_steps = std::max(4, static_cast<int>(std::ceil(max_range / occ_cell_size)));
    const int min_step = std::max(4, static_cast<int>(std::ceil(1.00f / occ_cell_size)));

    #pragma omp parallel for schedule(dynamic, 1024)
    for (int32_t i = 0; i < n_pts; ++i) {
        const float px = xyz[3 * i + 0];
        const float py = xyz[3 * i + 1];
        const float pz = xyz[3 * i + 2];
        const float self_f_rug  = fine_features[6 * i + 0];
        const float self_f_plan = fine_features[6 * i + 1];
        const float self_f_scat = fine_features[6 * i + 2];
        const float self_f_disp = fine_features[6 * i + 5];
        const float self_c_plan = coarse_features[6 * i + 1];

        const float self_rock_coherence =
            std::clamp((std::max(self_f_plan, self_c_plan) - 0.18f) * 3.0f, 0.25f, 1.0f) *
            std::clamp(1.0f - (self_f_disp - 0.42f) * 2.5f, 0.0f, 1.0f) *
            std::clamp(1.0f - (self_f_scat - 0.34f) * 2.5f, 0.0f, 1.0f) *
            std::clamp(1.0f - (self_f_rug  - 0.16f) * 6.0f, 0.0f, 1.0f);

        int up_hits = 0;
        float roof_weighted_hits = 0.0f;

        for (int k = 0; k < K_CONE; ++k) {
            const Eigen::Vector3f& d = up_dirs[k];
            for (int s = min_step; s <= max_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    up_hits++;
                    roof_weighted_hits += cell_rock_weight[cid];
                    break;
                }
            }
        }

        int down_hits = 0;
        float down_rock_hits = 0.0f;
        for (int k = 0; k < K_CONE; ++k) {
            const Eigen::Vector3f& d = down_dirs[k];
            for (int s = min_step; s <= max_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz + d.z() * dist, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    down_hits++;
                    down_rock_hits += cell_rock_weight[cid];
                    break;
                }
            }
        }

        int lat_rock_hits = 0;
        const int max_lat_steps = std::min(max_steps, static_cast<int>(std::ceil(25.0f / occ_cell_size)));
        for (int k = 0; k < K_LAT; ++k) {
            const Eigen::Vector3f& d = lat_dirs[k];
            for (int s = min_step; s <= max_lat_steps; ++s) {
                float dist = s * occ_cell_size;
                int32_t ix, iy, iz;
                grid.point_to_cell(px + d.x() * dist, py + d.y() * dist, pz, ix, iy, iz);
                int32_t cid = grid.find_cell(ix, iy, iz);
                if (cid != -1 && grid.point_count[cid] >= 1) {
                    if (cell_rock_weight[cid] > 0.45f) {
                        lat_rock_hits++;
                    }
                    break;
                }
            }
        }

        const float up_occ = static_cast<float>(up_hits) / K_CONE;
        const float roof_occ = roof_weighted_hits / K_CONE;
        const float down_occ = static_cast<float>(down_hits) / K_CONE;
        const float down_rock_occ = down_rock_hits / K_CONE;
        const float lat_occ = static_cast<float>(lat_rock_hits) / K_LAT;

        // Enforce physical vertical raycast consistency on Floor vs. Ceiling normals:
        // - Floor has ceiling above it (up_occ > down_occ + 0.15) -> normal must point UP (nz > 0)
        // - Ceiling has floor below it (down_occ > up_occ + 0.15) -> normal must point DOWN (nz < 0)
        // - Exterior ground has neither above nor below -> normal must point UP (nz > 0)
        float nx = normals_inout[3 * i + 0];
        float ny = normals_inout[3 * i + 1];
        float nz = normals_inout[3 * i + 2];
        if (std::abs(nz) > 0.20f) {
            if (up_occ > down_occ + 0.15f && roof_occ > 0.15f && nz < 0.0f) {
                nx = -nx; ny = -ny; nz = -nz;
            } else if (down_occ > up_occ + 0.15f && down_rock_occ > 0.15f && nz > 0.0f) {
                nx = -nx; ny = -ny; nz = -nz;
            } else if (up_occ < 0.08f && down_occ < 0.08f && nz < 0.0f) {
                nx = -nx; ny = -ny; nz = -nz;
            }
            normals_inout[3 * i + 0] = nx;
            normals_inout[3 * i + 1] = ny;
            normals_inout[3 * i + 2] = nz;
        }

        // Combined 3D cavern enclosure score:
        // 1. Floor / lower walls / internal speleothems: covered by a coherent rock ceiling (roof_occ)
        // 2. Overhanging ceiling vaults (nz < -0.10): 2D rock surface with floor below or lateral walls
        // 3. Vertical shafts / fissures: 2D rock walls enclosed laterally (lat_occ >= 0.50) and vertically
        float ceiling_vault_score = 0.0f;
        if (nz < -0.10f) {
            float overhang_strength = std::clamp((-nz - 0.10f) / 0.40f, 0.0f, 1.0f);
            ceiling_vault_score = self_rock_coherence * overhang_strength *
                                  std::max(down_rock_occ, 0.7f * lat_occ);
        }
        float shaft_wall_score = self_rock_coherence * (
            std::sqrt(roof_occ * down_rock_occ) * 1.5f +
            0.70f * lat_occ * std::max({roof_occ, (lat_occ >= 0.50f ? down_rock_occ : 0.0f)})
        );

        float cavern_enclosure = std::clamp(
            std::max({roof_occ, ceiling_vault_score, shaft_wall_score}), 0.0f, 1.0f
        );

        enclosure_out[4 * i + 0] = up_occ;
        enclosure_out[4 * i + 1] = roof_occ;
        enclosure_out[4 * i + 2] = down_occ;
        enclosure_out[4 * i + 3] = cavern_enclosure;
    }
}

